export const PRODUCT = {

constituents: {
  packages: ["nonprofitcloud"],
  name: "Constituents",
  icon: "\u{1F465}",
  color: "#f59e0b",
  description: "The Constituents domain provides the shared foundation for people and organizations that interact with Nonprofit Cloud, including donors, volunteers, board members, program participants, case subjects, grant applicants, and partner organizations. Individuals are represented by Person Accounts, while organizations, households, and other groups use Business Accounts; relationships, hierarchies, household membership, and contact points add context to those records. Fundraising processes use constituent records for donor matching, gift transactions, soft credits, and specialized Contact Profile attributes, while program, case, volunteer, and grantmaking processes reference the same constituents. Administrators configure the account model during setup and protect constituent data through Salesforce permissions and sharing.",
  components: [
    {id:"person-accounts",name:"Person Accounts",icon:"\u{1F9D1}",desc:"Person Accounts represent individual constituents in Nonprofit Cloud, including donors, program participants, volunteers, and other stakeholders. They provide an individual account page where users can view constituent details, contact information, interactions, and fundraising summaries. Person Accounts are strongly recommended for Fundraising and Program Management, but they aren’t required for grantmakers that primarily make grants to organizations. Enabling Person Accounts is irreversible, and they aren’t supported for use with Nonprofit Success Pack.",tags:["Account","Contact","ContactProfile"],docs:["Nonprofit Cloud uses Person Accounts to represent individuals and can connect them to households, organizations, and other groups through Group Membership records. A Person Account can serve as the shared constituent record for fundraising, program delivery, case management, volunteer management, and grantmaking. Account pages can also present a chronological Timeline and permanent, searchable Interaction Summaries for stakeholder engagement.","Person Account pages can be configured with constituent contact information and fundraising components. Contact Point Address related records support multiple, seasonal, historical, primary, or undeliverable addresses, while automatic address synchronization can keep the account mailing address aligned with a Contact Point Address. Fundraising page configurations can also show donor giving summaries, RFM scores, relationship graphs, life events, and key information in a Summary Card.","Configure Person Accounts as part of the Nonprofit Cloud prerequisites and before setting up Fundraising features that depend on them. Consider the account model carefully because Person Accounts can’t be turned off after enablement. Organizations using Nonprofit Success Pack must follow the documented restriction that Person Accounts aren’t supported with NPSP."],docUrl:"https://help.salesforce.com/s/articleView?id=sales.account_person_enable.htm&type=5&language=en_US",connections:[{"planet":"households","desc":"Individuals are linked to households via Party Relationship Groups"},{"planet":"relationships","desc":"People form relationships with other constituents"},{"planet":"contact_points","desc":"Person accounts have addresses, emails, and phone numbers"}]},
    {id:"business-accounts",name:"Business Accounts",icon:"\u{1F3E2}",desc:"Business Accounts represent organizations, households, and other groups in Nonprofit Cloud. They support organization-level constituent activity, including fundraising and applications for grants. Business Account details can include contact and address information such as phone and billing address. Group Membership records can connect Business Accounts with individuals and other organizations.",tags:["Account"],docs:["Use Business Accounts for organizational constituents and for households or other groups in the Nonprofit Cloud account model. Grantmaking organizations that make most grants to organizations can use the Contact plus Business Account model instead of enabling Person Accounts. Account information can also be used in grant applications and funding award summaries to identify an applicant or recipient.","Business Account record pages can be configured for fundraising and relationship management. Account relationship graphs can use the Fundraising Business Account Relations template, while Summary Cards can display selected standard or custom fields. Business Accounts can also participate in donor workflows, including gift entry donor matching and donor document generation.","Store business contact addresses in account fields such as Billing Address. Nonprofit Cloud can also surface business milestones for a Business Account and provide a Timeline of stakeholder interactions. Access to Account records and their details follows configured Salesforce permissions and sharing."],connections:[{"planet":"relationships","desc":"Organizations form relationships with other organizations and individuals"},{"planet":"fundraising","desc":"Organizations can be donors and grant sources"}]},
    {id:"contact-profiles",name:"Contact Profiles",icon:"\u{1F4C7}",desc:"Contact Profiles extend constituent information with fundraising-oriented attributes in Nonprofit Cloud. A profile is associated with an Account and can store values such as donor classification and recurring donor type. Fundraising automation can use Contact Profile information when processing constituent roles and gift records. This keeps specialized fundraising details related to the shared constituent account.",tags:["ContactProfile"],docs:["Use a Contact Profile to maintain fundraising-specific information for a constituent associated with an Account. The profile can capture donor classification and recurring donor type without replacing the constituent’s core Account information. This separation lets fundraising processes use specialized attributes while other Nonprofit Cloud features continue to reference the same constituent.","Packaged fundraising automation can update an advancement type on a Contact Profile when a constituent role is inserted or updated, based on the rank of active constituent roles. Other advancement flows can populate Gift Transaction, Gift Commitment Schedule, and Gift Soft Credit fields from Contact Profile information. Those flows use the advancement type and the profile’s most recent graduation date."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_manage_donor_profiles.htm&type=5&language=en_US",connections:[{"planet":"gift_commitments","desc":"Contact profiles track recurring donor status"},{"planet":"fundraising","desc":"Donor profiles inform cultivation strategies"}]},
    {id:"account-hierarchies",name:"Account Hierarchies",icon:"\u{1F3D7}",desc:"Account Hierarchies organize related Account records through parent-child account relationships. They complement Group Membership records, which connect individuals and organizations to households and other groups. Relationship graphs can visualize Person Account or Business Account relations on donor profiles. Together, these structures help users understand how constituents and constituent groups are connected.",tags:["Account"],docs:["Use the Account ParentId relationship to place an Account beneath another Account in an account hierarchy. This structure is appropriate when the relationship between the records is organizational or hierarchical. Business Accounts can represent households and other groups within the configured Nonprofit Cloud account model.","Use Group Membership records when individuals and organizations must be connected to groups rather than represented only through an account parent relationship. Nonprofit Cloud setup includes enabling Person Accounts and configuring Group Memberships as foundational prerequisites. These connections support the broader stakeholder model used across fundraising, programs, cases, volunteers, and grantmaking.","Fundraising donor profiles can display account relationships by using Actionable Relationship Center graphs. Nonprofit Cloud provides separate default templates for Fundraising Business Account Relations and Fundraising Person Account Relations. Administrators create and configure the appropriate graph, then expose it on the donor profile for users."],connections:[{"planet":"relationships","desc":"Hierarchies complement relationship records between organizations"}]}
  ],
  dataFlow: ["Configure the Account model in setup, enable required constituent features, and secure record access with Salesforce permissions and sharing.","Create individuals as Person Accounts and organizations or groups as Business Accounts, then associate individuals with households and maintain account contact information.","Connect constituents through relationships, Group Memberships, and account hierarchies.","Classify donors with Contact Profiles, match them during gift entry, associate gift transactions with them, and attribute soft credits to appropriate constituents.","Use constituent records as program participants, case subjects, and volunteers across Nonprofit Cloud.","Register individual or organizational grant applicants as constituents for grantmaking processes."],
  connections: [{"planet":"households","desc":"Individuals belong to households"},{"planet":"relationships","desc":"Constituents have relationships"},{"planet":"contact_points","desc":"Accounts have contact information"},{"planet":"fundraising","desc":"Donors are constituents"},{"planet":"gift_transactions","desc":"Gift transactions belong to donors"},{"planet":"gift_entry","desc":"Donors matched during gift entry"},{"planet":"soft_credits","desc":"Soft credits attributed to constituents"},{"planet":"programs","desc":"Program participants are constituents"},{"planet":"case_management","desc":"Case subjects are constituents"},{"planet":"volunteers","desc":"Volunteers are constituents"},{"planet":"grantmaking","desc":"Grant applicants are constituents"},{"planet":"security","desc":"Constituent data access is secured"},{"planet":"setup","desc":"Account model configured in setup"}]
},

households: {
  packages: ["nonprofitcloud"],
  name: "Households & Groups",
  icon: "\u{1F3E0}",
  color: "#10b981",
  description: "Households & Groups models households and other affiliations through Party Relationship Groups and membership relationships in Nonprofit Cloud. Individuals belong to households through dated, role-based connections, and the model supports overlapping household or group affiliations. Household members can have additional inter-relationships and can share contact information while retaining constituent-specific addresses. Household address data can support outreach activities such as campaign mailings.",
  components: [
    {id:"party-relationship-groups",name:"Party Relationship Groups",icon:"\u{1F46A}",desc:"Party Relationship Groups provide a flexible way to represent households and other affiliations in Nonprofit Cloud. A group is associated with an account and can be classified by type, including Household, with start and end dates that define its duration. Individuals and organizations connect to groups through membership records, allowing a constituent to participate in more than one household or other group.",tags:["PartyRelationshipGroup"],docs:["Nonprofit Cloud uses Person Accounts to represent individuals and Business Accounts to represent households and other groups. A Party Relationship Group identifies a named group, associates it with an account, and records its type. Start and end dates support groups whose relevance or composition changes over time.","Membership connections associate individuals or organizations with a group rather than placing every constituent into a single fixed household structure. This approach supports overlapping affiliations, including membership in multiple households or other groups. The resulting group and relationship information can contribute to a unified understanding of stakeholders and their connections."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.group_membership_set_up.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Groups contain individual constituents as members"},{"planet":"relationships","desc":"Group members have inter-relationships"}]},
    {id:"household-membership",name:"Household Membership",icon:"\u{1F511}",desc:"Household Membership connects an individual to a household represented by a Party Relationship Group. Account Contact Relationship records capture the participating account and contact, membership roles, active status, and applicable dates. Household members can also have inter-relationships, and a person can belong to multiple groups when needed.",tags:["AccountContactRelation"],docs:["Create household membership by connecting an individual to the account associated with the household group. The Account Contact Relationship identifies the account and contact and records whether the membership is active. Start and end dates preserve the period during which the membership applies.","Use roles such as Head of Household, Member, or Dependent to describe how an individual participates in the household. Because membership is maintained through relationship records, the same individual can be connected to more than one household or affinity group. Related relationship information can describe connections among household members in addition to their shared group affiliation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.group_membership_how_nonprofit_cloud_models_groups_relationships.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Members are Person Account constituents"},{"planet":"relationships","desc":"Membership roles complement interpersonal relationships"}]},
    {id:"household-addressing",name:"Household Addressing",icon:"\u{1F4EC}",desc:"Household Addressing supports the use of household and constituent address information for outreach, including campaign mailings. Nonprofit Cloud uses contact address fields for constituents and account address fields for business contacts. Organizations can also track multiple or historical constituent addresses so communications use the address that is currently in effect.",tags:["PartyRelationshipGroup"],docs:["Address management keeps constituent contact information accurate and organized. For constituents, use contact fields such as Mailing Address; for business contacts, use account fields such as Billing Address. Household records can provide shared contact information while individual records retain constituent-specific details.","Constituents can have multiple addresses that apply at different times of the year, and organizations can retain historical addresses. Maintaining these records helps teams send outreach materials and gift acknowledgments to the address currently used by the constituent. Household address information can also support addressing decisions for campaign mailings."],connections:[{"planet":"contact_points","desc":"Household members share contact point addresses"},{"planet":"campaigns","desc":"Household addressing supports campaign mailings"}]}
  ],
  dataFlow: ["Create or identify the individual constituent records.","Create the household account and its Party Relationship Group.","Add household members with roles, active status, and membership dates.","Maintain member inter-relationships and any overlapping group affiliations.","Update shared and constituent-specific contact information.","Use current household addressing data for campaign mailings."],
  connections: [{"planet":"constituents","desc":"Individuals belong to households"},{"planet":"relationships","desc":"Household members have inter-relationships"},{"planet":"contact_points","desc":"Households share contact information"},{"planet":"campaigns","desc":"Household addressing for campaign mailings"}]
},

relationships: {
  packages: ["nonprofitcloud"],
  name: "Relationships",
  icon: "\u{1F91D}",
  color: "#8b5cf6",
  description: "Relationships in Nonprofit Cloud track connections among constituents, including individual-to-individual, individual-to-organization, and organization-to-organization ties. Contact relationships capture personal connections, while account relationships provide household, affiliation, partnership, and other organizational context. Configurable Party Role Relationships supply consistent relationship types and reciprocal labels. This connected view supports household understanding, soft credit decisions, fundraising engagement, and grantmaking analysis.",
  components: [
    {id:"contact-contact-relationships",name:"Contact Contact Relationships",icon:"\u{1F46B}",desc:"Contact Contact Relationships record connections between individual constituents, including spouses, parents and children, and colleagues. Each relationship identifies a contact, a related contact, and the role that characterizes their connection. Active status and start-date information support ongoing relationship tracking. These relationships can provide context for household membership, donor engagement, and soft credit decisions.",tags:["ContactContactRelation"],docs:["Use Contact Contact Relationships to model personal connections between constituents. A relationship links the contact in ContactId to the contact in RelatedContactId. RoleId identifies the configured role that describes the connection, such as a family or professional relationship.","Use IsActive to indicate whether the relationship is current, and StartDate to record when it began. This information helps staff understand the people connected to a constituent when reviewing donor and stakeholder data. It can also inform household context and decisions about recognizing people who influenced a gift through soft credits."],connections:[{"planet":"constituents","desc":"Links individual Person Account records"},{"planet":"soft_credits","desc":"Relationships inform soft credit attribution for gifts"}]},
    {id:"account-contact-relationships",name:"Account Contact Relationships",icon:"\u{1F4BC}",desc:"Account Contact Relationships represent connections between individuals and organizations. Nonprofit Cloud can use Person Accounts for individuals and Business Accounts for households, other groups, and organizations. These connections help staff understand a constituent’s organizational affiliations and broader stakeholder context. They can support relationship-based fundraising and grantmaking work.",tags:["AccountContactRelation"],docs:["Use Account Contact Relationships to capture how an individual is connected to an organization. In the Nonprofit Cloud data model, Person Accounts can represent individuals, while Business Accounts can represent households, groups, and organizations. Salesforce relationship and group-membership capabilities connect individuals and organizations to one another.","These relationships provide organizational context when staff evaluate or engage a constituent. Fundraising teams can use that context to understand professional affiliations and identify opportunities for deeper engagement. Grantmaking teams can also consider connections between people and applicant or recipient organizations."],connections:[{"planet":"constituents","desc":"Links individuals to organizations"},{"planet":"households","desc":"ACRs link household members to household groups"}]},
    {id:"account-account-relationships",name:"Account Account Relationships",icon:"\u{1F3E2}",desc:"Account Account Relationships model connections between organizations, households, and other account-based groups. They can represent organizational affiliations, partnerships, and related institutional ties. Each record identifies two accounts, assigns a configured role, and indicates whether the relationship is active. Account relationships can be displayed graphically on a donor profile to help users understand connected people and businesses.",tags:["AccountAccountRelation"],docs:["Use Account Account Relationships to record a connection between the account in AccountId and the account in RelatedAccountId. RoleId identifies the configured role that characterizes the connection. IsActive indicates whether the organizational relationship is current.","Nonprofit Cloud can present account relationships through an Actionable Relationship Center graph on the donor profile. Actionable Relationship Center provides an interactive display that helps users understand relationships among people and businesses. This organizational context can inform fundraising engagement and decisions involving grant applicants or recipients."],connections:[{"planet":"constituents","desc":"Links organization accounts together"},{"planet":"grantmaking","desc":"Organization relationships inform grantmaking"}]},
    {id:"party-role-relationships",name:"Party Role Relationships",icon:"\u{1F3F7}",desc:"Party Role Relationships define the relationship types that can be applied to connections between parties in Nonprofit Cloud. Each definition has a name, a reciprocal label, a relationship type, and an active status. Reciprocal labels describe the relationship from the perspective of the related party. Administrators configure and activate these definitions during setup so relationship records use consistent terminology.",tags:["PartyRoleRelation"],docs:["Use Party Role Relationships to establish the available relationship classifications for constituent and organization connections. Name identifies the role, while ReciprocalLabel provides the corresponding label from the other party’s perspective. RelationshipType categorizes the definition for relationship usage.","Use IsActive to control whether a relationship definition is available for current use. Configure these definitions in setup before applying roles to relationship records. Consistent role definitions help staff interpret personal, household, and organizational connections across Nonprofit Cloud."],connections:[{"planet":"setup","desc":"Relationship types are configured by admins in setup"}]}
  ],
  dataFlow: ["Configure active relationship types and reciprocal labels in setup.","Connect constituents through individual, household, and organizational relationship records.","Assign the appropriate role and record current status or start-date details where available.","Review household-member and organization connections in constituent profiles and relationship graphs.","Use relationship context to inform soft credit decisions, fundraising engagement, and grantmaking work."],
  connections: [{"planet":"constituents","desc":"Relationships connect constituents"},{"planet":"households","desc":"Household members have relationships"},{"planet":"soft_credits","desc":"Relationships inform soft credit decisions"},{"planet":"grantmaking","desc":"Organization relationships inform grants"},{"planet":"setup","desc":"Relationship types configured in setup"}]
},

contact_points: {
  packages: ["nonprofitcloud"],
  name: "Contact Information",
  icon: "\u{1F4DE}",
  color: "#06b6d4",
  description: "Contact Information in Nonprofit Cloud manages address, email, and phone records associated with constituent accounts. Multiple contact points can be maintained for an individual or organization, with a primary designation identifying the preferred record. Household members can share contact information, and current contact points support campaign outreach and constituent service. Address management also supports seasonal usage, undeliverable status, and synchronization with Person Account mailing addresses.",
  components: [
    {id:"contact-point-addresses",name:"Contact Point Addresses",icon:"\u{1F4CD}",desc:"Contact Point Addresses store mailing and physical address information associated with constituent accounts in Nonprofit Cloud. An account can have additional, primary, temporary, inactive, or seasonal addresses to support accurate correspondence. Users can identify the primary address and track addresses that are seasonal or undeliverable. These records support household contact information and address selection for campaign outreach.",tags:["ContactPointAddress"],docs:["Users add an address from the Contact Point Addresses related list on an account and provide a record name, address details, usage type, and primary designation. Supported usage examples include Home, Work, Temporary, and Inactive. Seasonal start and end information can identify when an address should be used, such as for a winter home or college dormitory.","Automatic Person Account Mailing Address Synchronization keeps the primary Contact Point Address and Person Account mailing address aligned when the required flow is configured and activated. Selecting Is Primary identifies the address for the donor profile and mailed outreach; removing the designation clears it from the Person Account mailing address fields. Administrators must provide users with appropriate access to the address, Is Primary, and Is Undeliverable fields on Contact Point Address and to the Person Account mailing address fields.","When returned mail indicates that an address is invalid, users can mark the Contact Point Address as undeliverable. If that record is also primary, automatic synchronization removes it from the Person Account mailing address to prevent further correspondence to that address. Before sending seasonal correspondence, users should review the seasonal dates and select the address appropriate for the mailing date."],connections:[{"planet":"constituents","desc":"Addresses belong to constituent accounts"},{"planet":"campaigns","desc":"Addresses used for direct mail campaigns"},{"planet":"households","desc":"Household members may share addresses"}]},
    {id:"contact-point-emails",name:"Contact Point Emails",icon:"\u{1F4E7}",desc:"Contact Point Emails store constituent email addresses associated with accounts in Nonprofit Cloud. Each record captures an email address and its type and can be designated as primary. Multiple contact records allow constituent contact information to be maintained separately rather than reduced to a single value. Current email information supports constituent service and campaign outreach.",tags:["ContactPointEmail"],docs:["Users can update constituent contact information while handling requests from existing or prospective donors. ContactPointEmail records associate an email address with an account through ParentId, classify it with EmailType, and identify a preferred record with IsPrimary. This information can be reviewed alongside other donor details when matching and supporting a constituent."],connections:[{"planet":"constituents","desc":"Emails belong to constituent accounts"},{"planet":"campaigns","desc":"Email addresses used for outreach"}]},
    {id:"contact-point-phones",name:"Contact Point Phones",icon:"\u{260E}",desc:"Contact Point Phones store constituent telephone numbers associated with accounts in Nonprofit Cloud. Each record captures a telephone number and phone type and can be marked as primary. Multiple phone records support maintaining distinct contact details for a constituent. Current phone information helps users respond to constituent requests and supports campaign outreach.",tags:["ContactPointPhone"],docs:["Users can review and update constituent contact information while responding to existing or prospective donors. ContactPointPhone records associate a telephone number with an account through ParentId, classify it with PhoneType, and identify a preferred record with IsPrimary. The records provide structured phone information when users search for and match a donor record during an interaction."],connections:[{"planet":"constituents","desc":"Phone numbers belong to constituent accounts"}]}
  ],
  dataFlow: ["Identify the constituent or household account that owns the contact information.","Create address, email, and phone contact point records for the account.","Classify each contact point and designate the appropriate primary record.","Maintain seasonal and undeliverable address details as circumstances change.","Keep shared household contact information current for household members.","Use current contact points for constituent service and campaign outreach."],
  connections: [{"planet":"constituents","desc":"Contact information belongs to accounts"},{"planet":"households","desc":"Household members share contact information"},{"planet":"campaigns","desc":"Contact points used for campaign outreach"}]
},

fundraising: {
  packages: ["nonprofitcloud"],
  name: "Fundraising Pipeline",
  icon: "\u{1F4B0}",
  color: "#ef4444",
  description: "The Fundraising Pipeline domain manages major gift and grant solicitations in Nonprofit Cloud through opportunities associated with donor constituents, campaigns, gift default designations, and configurable opportunity processes. Action Plans can organize repeatable cultivation work, while Fundraising rollups, RFM scoring, and Fundraising Intelligence help teams prioritize donors, opportunities, and campaigns. Successful solicitations connect to gift commitments that produce gift transactions, while influence recognition is recorded separately through Gift Default Soft Credit or Gift Soft Credit records rather than Opportunity Contact Roles. Fundraising Settings are configured in Setup, inbound grants use the opportunity pipeline, Agentforce supports documented fundraising research and engagement workflows, and Einstein Copilot produces draft gift proposals.",
  components: [
    {id:"opportunities",name:"Opportunities",icon:"\u{1F3AF}",desc:"Opportunities track major gift and grant solicitations in the Nonprofit Cloud fundraising pipeline. They can be associated with donors, campaigns, record types, and gift default designations while progressing through organization-defined stages. Gift commitments can be connected to opportunities, and inbound grants use opportunities alongside gift commitments, schedules, and transactions. Opportunity data also supports major-donor analysis in Fundraising Intelligence.",tags:["Opportunity"],docs:["The Philanthropy & Partnerships app provides a central workspace for major giving and grant solicitations. Fundraisers can research major donors and grantmakers, record interactions, and manage the steps required to cultivate and solicit large gifts. Opportunities represent solicited fundraising activity and can be related to campaigns and donor accounts.","Opportunities can supply Gift Default Designations for related gift commitments. In the gift default designation inheritance hierarchy, a commitment first inherits designations from its associated opportunity, then from its campaign, and finally from the org-wide default designation. Administrators add the Gift Default Designations related list to the Opportunity object so users can allocate or modify these defaults.","Inbound grants are represented with opportunities, gift commitments, gift commitment schedules, and gift transactions. Administrators prepare grant solicitation processes on the Opportunity object by configuring a record type, stage values, and a Sales Process, and they can add grant-specific fields and page layouts. Einstein Copilot can use Salesforce org data to produce draft gift proposals through Copilot Actions: Fundraising Gift Proposals."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_learn_about_nonprofit_cloud_fundraising.htm&type=5&language=en_US",connections:[{"planet":"gift_commitments","desc":"Won opportunities become gift commitments"},{"planet":"campaigns","desc":"Opportunities are sourced from campaigns"},{"planet":"designations","desc":"Opportunities can have default gift designations"}]},
    {id:"opportunity-contact-roles",name:"Opportunity Contact Roles",icon:"\u{1F464}",desc:"Opportunity Contact Roles associate contact records with an Opportunity and capture their role in the solicitation. OpportunityId and ContactId identify the related opportunity and contact, Role records the contact’s involvement, and IsPrimary marks the primary contact. These records provide relationship context for the opportunity but are not the documented mechanism for recognizing influence on a resulting gift. Nonprofit Cloud records gift influence separately through Gift Soft Credit or Gift Default Soft Credit records.",tags:["OpportunityContactRole"],docs:["An Opportunity Contact Role links an Opportunity to a contact involved in that opportunity. The OpportunityId and ContactId fields establish the association, while Role describes the contact’s participation. IsPrimary indicates which associated contact is primary for the opportunity.","Opportunity Contact Roles must not be used as a substitute for gift soft credits. Nonprofit Cloud recognizes constituents other than the donor by creating Gift Soft Credit records on gift transactions or Gift Default Soft Credit records on gift commitments. Gift entry can also capture soft-credit details and generate the corresponding Gift Soft Credit records during processing."],connections:[{"planet":"constituents","desc":"Contact roles reference person accounts"},{"planet":"soft_credits","desc":"Contact roles inform soft credit attribution"}]},
    {id:"sales-processes",name:"Sales Processes",icon:"\u{1F4C8}",desc:"Sales Processes define the stage progression used for fundraising opportunities in Nonprofit Cloud. For inbound grants, administrators configure a grant solicitation process on the Opportunity object with a record type, stage values, and a Sales Process. Record types and grant-specific page layouts can separate this process from other opportunity workflows. Opportunity fields such as StageName, Probability, CloseDate, and RecordTypeId capture the opportunity’s current pipeline state and expected timing.",tags:["Opportunity"],docs:["Nonprofit Cloud uses opportunities for major gift and grant solicitations, with the Philanthropy & Partnerships app supporting the work required to cultivate and solicit large gifts. A Sales Process determines the stage values available to the associated opportunity process. Opportunity stages and related values provide the structure used to monitor solicitation progress.","For inbound grants, administrators set up grant solicitation processes directly on the Opportunity object. The documented configuration includes a record type, stage values, and a Sales Process, with optional grant-specific custom fields and a grant-specific page layout. Administrators also create and assign a permission set for users who need access to grant-related functionality."],connections:[{"planet":"setup","desc":"Sales processes are configured by admins"},{"planet":"action_plans","desc":"Stage transitions can trigger action plans"}]},
    {id:"fundraising-analytics",name:"Fundraising Analytics",icon:"\u{1F4CA}",desc:"Fundraising Analytics combines fundraising rollups, RFM scoring, and Fundraising Intelligence dashboards to help teams evaluate donors, opportunities, campaigns, and organizational performance. Data Processing Engine calculates donor and fundraising summaries, while configured RFM scores support reporting, segmentation, list building, and solicitation planning. Fundraising Intelligence uses Tableau Next dashboards integrated with Data 360 to analyze major-donor opportunities, mass-market campaigns, and overall fundraising performance. These insights help fundraisers identify high-value donors, prioritize engagement, and refine campaign strategies.",tags:["Opportunity"],docs:["Fundraising rollups use Data Processing Engine to summarize donor giving, gift designations, and outreach performance. Administrators clone and activate the DonorGiftSummary, GiftDesignation, OutreachSummary, and Fundraising Account Actionable List templates, then run them manually or through scheduled flows. Donor Giving Summary, Gift Designation Summary, Campaign Summary, and Outreach Source Code Summary components expose the resulting metrics in Fundraising apps.","Recency, Frequency, and Monetary Value (RFM) scoring identifies donors based on how recently they gave, how frequently they give, and the monetary value of their gifts. Administrators configure source and destination fields, component weights, and scoring ranges, and the RFM Score Calculation data processing engine definition creates the scores. Fundraisers can use individual and composite RFM scores for reporting, segmentation, list building, campaign targeting, and gift proposal planning.","Fundraising Intelligence is a suite of Tableau Next dashboards integrated with Data 360. Its Major Donor Insights dashboard analyzes donor opportunities by stage, value, donor count, and follow-up priority; Mass Market Insights analyzes campaign revenue, donors, return on investment, and performance over time. Fundraising Performance Insights provides an organization-wide view of funds raised, paid transactions, donors, campaign performance, and opportunity value.","Administrators use the Fundraising Intelligence guided setup to assign access, connect the Salesforce org to Data 360, create Fundraising Data Bundle data streams, ingest the data, and install the app. The dashboards are embedded by default on the Philanthropy and Partnerships, Donor Engagement, and Fundraising Strategy home pages. If those pages are customized, administrators add the Fundraising Intelligence Dashboard component with Lightning App Builder."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.npc_fr_set_up_rfm_scoring.htm&language=en_US",connections:[{"planet":"campaigns","desc":"Analytics track campaign effectiveness"},{"planet":"designations","desc":"Analytics show designation-level totals"}]}
  ],
  dataFlow: ["Configure Fundraising Settings, opportunity record types, stage values, Sales Processes, and grant-specific access in Setup.","Identify donor constituents and create opportunities from campaigns for major gifts, inbound grants, or other tracked solicitations.","Assign gift default designations and Opportunity Contact Roles, then use Action Plans to organize repeatable cultivation tasks.","Advance opportunities through their stages, use fundraising analytics to prioritize engagement, and use Agentforce for supported research and engagement workflows or Einstein Copilot for draft gift proposals.","Create gift commitments from successful opportunities and process their schedules or gift entries into gift transactions.","Record giving influence separately as Gift Default Soft Credit or Gift Soft Credit records on commitments, transactions, or gift entries."],
  connections: [{"planet":"constituents","desc":"Donors are constituents"},{"planet":"gift_commitments","desc":"Opportunities become commitments"},{"planet":"gift_transactions","desc":"Opportunities produce transactions"},{"planet":"campaigns","desc":"Campaigns source fundraising"},{"planet":"designations","desc":"Opportunities have default designations"},{"planet":"soft_credits","desc":"Opportunity contact roles drive soft credits"},{"planet":"agentforce","desc":"AI generates gift proposals"},{"planet":"action_plans","desc":"Action plans drive cultivation steps"},{"planet":"setup","desc":"Fundraising settings in setup"},{"planet":"grantmaking","desc":"Grants use the fundraising pipeline"}]
},

gift_commitments: {
  packages: ["nonprofitcloud"],
  name: "Gift Commitments",
  icon: "\u{1F4DD}",
  color: "#f97316",
  description: "Gift Commitments in Nonprofit Cloud record donor promises for pledges, multipayment gifts, recurring donations, and in-kind contributions. Commitments can be created through gift entry or from opportunities, attributed to campaigns, and allocated to donor-selected gift designations. Recurring and custom schedules establish expected payment timing and drive the creation or update of gift transactions. Lifecycle actions modify amounts, dates, payment details, pauses, resumptions, or closure, while the Gift Commitment Change Attribution Log captures details about those changes.",
  components: [
    {id:"commitment-records",name:"Commitment Records",icon:"\u{1F4DC}",desc:"Commitment Records represent donor promises for monetary and in-kind gifts in Nonprofit Cloud. They support one-time pledges, multipayment gifts, and open-ended recurring gifts, and can be created through gift entry or associated with an opportunity. A commitment can also be attributed to a campaign and allocated among gift designations selected by the donor. Commitment records provide the basis for schedules, gift transactions, and subsequent donor-requested changes.",tags:["GiftCommitment"],docs:["A Gift Commitment records the donor, commitment name, schedule type, status, Expected Total Commitment Amount, and Effective Start Date. When creating a commitment, users select Recurring for a set amount paid on a recurring schedule or Custom for a nonrecurring commitment paid in one or more installments. Gift commitments can also be added through Gift Entry, including when creating a new recurring gift.","A commitment can be connected to an opportunity and campaign. Gift Default Designations allocate the commitment amount to the donor’s selected purposes and can be inherited from the associated opportunity or campaign. If no applicable Gift Default Designations exist, the org-wide default designation is used, and any allocation below 100% leaves the remainder for that default designation.","Nonprofit Cloud also records in-kind donations as gift commitments. Users can identify an expected asset transfer and record the present value, expected transfer date and value, and expected maturity date and value when those fields are included on the page layout. Organizations are responsible for following applicable laws when recording and acknowledging non-monetary gifts."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_commitments.htm&type=5&language=en_US",connections:[{"planet":"fundraising","desc":"Commitments originate from fundraising opportunities"},{"planet":"gift_transactions","desc":"Commitments generate scheduled transactions"},{"planet":"designations","desc":"Commitments inherit default designations"}]},
    {id:"commitment-schedules",name:"Commitment Schedules",icon:"\u{1F4C5}",desc:"Commitment Schedules define when and how amounts promised through Gift Commitments are expected to be paid. Nonprofit Cloud supports recurring schedules for ongoing donations and custom schedules for pledges, one-time gifts, and other nonrecurring commitments. Schedule details include the Transaction Period, Transaction Amount, Transaction Day, Start Date, and End Date. Creating or updating schedules through the Gift Commitment page automatically creates or updates associated gift transactions.",tags:["GiftCommitmentSchedule"],docs:["A recurring Gift Commitment Schedule specifies a Start Date, optional End Date, Transaction Period, Transaction Day when applicable, and Transaction Amount. Users can also select a payment method and provide payment instrument information. When ACH or credit card is selected and at least the Last 4 field is populated, Nonprofit Cloud adds a payment instrument lookup to the schedule and creates a payment instrument record if one doesn’t already exist.","A custom schedule represents a nonrecurring payment and uses its Start Date as the transaction due date. Users enter the Transaction Amount and payment details for each scheduled payment. Custom schedules can be used for commitments such as pledges or one-time gifts, while a Custom transaction period isn’t valid for a commitment with a recurring schedule type.","When schedules are created or managed from the Gift Commitment page, Nonprofit Cloud automatically creates or updates gift transactions. Gift transactions are created for schedules that are created or updated when standard or custom schedule fields change. If an organization manages schedules outside that page, it must manually create or update transactions or use the Manage Gift Commitment Schedule invocable action through a flow."],connections:[{"planet":"gift_transactions","desc":"Schedules trigger gift transaction creation"},{"planet":"gift_entry","desc":"Gift entry can create new commitment schedules"}]},
    {id:"commitment-lifecycle",name:"Commitment Lifecycle",icon:"\u{1F504}",desc:"Commitment Lifecycle operations keep recurring Gift Commitments and their related schedules and transactions aligned with donor instructions. Users can upgrade or downgrade amounts, change dates or payment methods, pause and resume schedules, and close commitments. Nonprofit Cloud processes these changes against affected schedules and unpaid transactions. The Gift Commitment Change Attribution Log captures details used to attribute commitment changes.",tags:["GiftCommitment","GiftCommitmentSchedule"],docs:["Users can change the amount, schedule, allocation, dates, or payment method of a recurring gift commitment. If a change applies only to part of a schedule, Nonprofit Cloud splits the schedule around the effective date range and preserves portions before or after the change as applicable. Existing unpaid gift transactions with due dates in the effective period are removed when the commitment is processed.","A recurring schedule can be paused for a fixed period or indefinitely and resumed when the donor is ready to continue. Pausing a schedule after its Start Date splits the schedule and creates a schedule with the type Pause Transactions for the pause period. Unpaid gift transactions whose due dates fall within that period are removed. The Pause | Resume flow performs these schedule operations.","Processing evaluates Gift Commitment Schedules and Gift Transactions to update the next transaction information, current schedule information, and commitment status. Depending on the schedule and transaction conditions, a commitment can become Active, Paused, Lapsed, Failing, or Closed. Closing a commitment updates associated unpaid or failed transactions based on the Formal Commitment Type. Changes are recorded in the Gift Commitment Change Attribution Log, including the Change Per Day Amount and the campaign and outreach source code associated with the change."],connections:[{"planet":"gift_transactions","desc":"Lifecycle changes affect future transactions"},{"planet":"campaigns","desc":"Upgrades can be attributed to campaigns"}]}
  ],
  dataFlow: ["Create a commitment through gift entry or from an opportunity.","Attribute the commitment to a campaign.","Allocate the committed amount to gift designations.","Define a recurring or custom commitment schedule.","Generate and update gift transactions from the schedule.","Process lifecycle changes and record their attribution."],
  connections: [{"planet":"fundraising","desc":"Opportunities become commitments"},{"planet":"gift_transactions","desc":"Commitments generate transactions"},{"planet":"gift_entry","desc":"Gift entry creates commitments"},{"planet":"designations","desc":"Commitments allocated to designations"},{"planet":"campaigns","desc":"Commitments attributed to campaigns"}]
},

gift_transactions: {
  packages: ["nonprofitcloud"],
  name: "Gift Transactions",
  icon: "\u{1F4B3}",
  color: "#ec4899",
  description: "Gift Transactions in Nonprofit Cloud record one-time gifts, installments that fulfill gift commitments, matching gifts linked to their initial donations, and non-revenue gifts. Gift entry creates or updates transactions, while gift commitment scheduling and broader fundraising activity can also lead to transaction records; each donor is represented by a constituent account. Transactions can be attributed to campaigns and outreach source codes, allocated to gift designations, and associated with gift soft credits for constituents who influenced the gift. They also track payment details and acknowledgment status and support full or partial refunds that preserve the original gift history.",
  components: [
    {id:"transaction-records",name:"Transaction Records",icon:"\u{1F9FE}",desc:"Transaction Records track one-time gifts, installments that fulfill gift commitments, matching gifts, and non-revenue gifts in Nonprofit Cloud. Fundraising creates or updates gift transactions when users process gift entries and also creates them when users schedule and process gift commitments. Each transaction can identify its constituent account donor, Gift Type, amount, status, Transaction Date, Payment Method, campaign, outreach source code, and related gift commitment. Transactions can also be allocated to gift designations and associated with gift soft credits that recognize constituents who influenced the gift.",tags:["GiftTransaction"],docs:["A Gift Transaction represents a one-time gift payment, an installment of a gift commitment, or a non-revenue gift. Users can create a transaction manually when an installment doesn’t exist, but Fundraising automatically creates transactions when a gift entry is processed or a gift commitment is scheduled and processed. For example, scheduling a recurring commitment creates a transaction for its next installment when the applicable Fundraising setting is selected. Gift entry processing can also generate the related Gift Transaction Designation and Gift Soft Credit records.","When creating a Gift Transaction manually, users select Gift Type as Individual or Organizational/Household and then select the corresponding donor account. An Individual gift uses a person account, while an Organizational/Household gift uses a business account. Users enter payment information, Original Amount, and a Transaction Date that can reflect the date on the check or the date the gift was received. Setting the amount to zero records a non-revenue transaction.","Gift transactions can be attributed to a gift commitment, campaign, donor, and outreach source code. Transaction amounts can be allocated among Gift Transaction Designations according to donor-selected amounts or percentages, with any unallocated remainder assigned to the org-wide default designation. Gift Soft Credit records recognize constituents other than the donor who influenced the gift, including tribute honorees. For a matching gift, the Matching Employer Transaction lookup on the initial donation is updated with the newly created matching gift transaction.","A transaction’s Status indicates its current state, and permitted status changes depend on its existing status. Gift entries paid by cash or check create paid transactions, while other payment methods create pending transactions. Users can review upcoming, missed, failed, recently paid, and refunded transactions from the related gift commitment. GiftTransaction supports standard Salesforce features including Path and kanban views."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_transactions.htm&type=5&language=en_US",connections:[{"planet":"gift_commitments","desc":"Transactions fulfill commitment installments"},{"planet":"designations","desc":"Transactions are allocated to designations"},{"planet":"soft_credits","desc":"Transactions can have soft credit recipients"},{"planet":"campaigns","desc":"Transactions attributed to campaigns"}]},
    {id:"payment-instruments",name:"Payment Instruments",icon:"\u{1F4B1}",desc:"Payment Instruments store account-related payment method details used with gift transactions and gift commitment schedules in Nonprofit Cloud. Payment Instrument fields can be added to the Gift Transaction and Gift Commitment Schedule Lightning page layouts to capture details required to complete a transaction. For ACH or credit card payments, providing at least Last 4 adds a Payment Instrument lookup and creates a Payment Instrument record when no matching record already exists.",tags:["PaymentInstrument"],docs:["Payment Instruments support payment details associated with gift transactions and gift commitment schedules. Nonprofit Cloud admins can add Payment Instrument fields to the Gift Transaction and Gift Commitment Schedule Lightning page layouts. The fields capture account holder and payment method details required to complete a transaction.","When users create a Gift Transaction or configure a Gift Commitment Schedule, they can select a Payment Method and enter associated information such as Last 4 and expiration dates. For a Payment Method of ACH or credit card, populating at least Last 4 adds a Payment Instrument lookup to the schedule. If no Payment Instrument record already exists, Nonprofit Cloud creates one.","Payment method details can be updated for a specific period of a recurring gift commitment schedule. Users select the schedule, Payment Method, payment instrument details, and effective dates for the change. The Donor Support Profile can also expose payment instrument details so support staff can verify or update payment information for gift transactions and commitments."],connections:[{"planet":"gift_commitments","desc":"Payment instruments link to commitment schedules"}]},
    {id:"refund-processing",name:"Refund Processing",icon:"\u{1F501}",desc:"Refund Processing returns all or part of a paid gift amount while preserving the complete transaction history in Nonprofit Cloud. Users create a Gift Refund from the paid Gift Transaction and provide the refund amount, refund date, and refund status. When a refund is completed, Nonprofit Cloud updates the refund amount and current amount on the related transaction without changing its original amount.",tags:["GiftTransaction"],docs:["A Gift Refund can correct a gift entry mistake or honor a donor’s request to reverse a gift. Users open the paid Gift Transaction, create a record from the Gift Refunds related list, and enter the refund amount, date, and status. The refund can cover the full transaction amount or only part of it, preserving the original transaction and its history.","When the refund Status is Completed and the record is saved, Nonprofit Cloud updates the refund amount and current amount fields on the related Gift Transaction. The Original Amount remains unchanged. After processing the refund, users update the Gift Transaction Status as needed; an admin can add a validation rule to verify that the selected status is consistent with the refunded amount.","A fully refunded Gift Transaction can’t be changed to another status. Refund records and recently refunded transactions can be reviewed from the related gift commitment, and GiftRefund supports Path and kanban views. Donor portals created with Experience Cloud can also show refund information alongside gift commitments, transactions, soft credits, and tributes."],connections:[{"planet":"designations","desc":"Refunds adjust designation allocation amounts"}]},
    {id:"acknowledgments",name:"Acknowledgments",icon:"\u{2709}",desc:"Acknowledgments provide personalized gift acknowledgments and tax receipts to donors in Nonprofit Cloud. Acknowledgment generation uses customized templates and Salesforce DocGen to create documents for individual donors or batches of transactions. Generating a document can update the acknowledgment status on the associated Gift Transaction records and store the resulting PDF in Salesforce.",tags:["GiftTransaction"],docs:["Gift acknowledgments help organizations thank donors, comply with applicable tax laws, and maintain donor relationships. Nonprofit Cloud uses Salesforce DocGen and organization-specific templates to generate personalized acknowledgments and tax receipts. Templates can include supported Account, Gift Commitment, Gift Transaction, Gift Transaction Designation, and Gift Tribute data.","Users can generate a single donation receipt from an Account page in the Fundraising Strategy or Donor Engagement app. They select a document template, a transaction date range, and optional Transaction Status and Acknowledgment Status filters. The generation process can update the acknowledgment status of the selected Gift Transaction records. When the job finishes, the generated PDF is available under Files on the Document Generation Query Result record.","Users can generate batches of personalized acknowledgments from the Fundraising Operations home page. Batch criteria can filter transactions by date and by fields on objects that Gift Transaction looks up to, as well as Gift Designation. The batch can update acknowledgment and tax receipt statuses after the Salesforce DocGen job completes, and it can optionally produce a report of included donors. Recent Batches provides job status, run date, and links to the Document Generation Query Result and document template for batches run during the past seven days.","Admins enable server-side documentation generation, configure the DocGen Document Template Library, provide users access through a public group, and add acknowledgment templates to the library. The Generate Document action can be added to Account and Person Account page layouts, while Generate Document Batch is available on the Fundraising Operations home page by default. Organizations that accept multiple currencies can create separate templates for each accepted currency and filter batches for the currency used by the template."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_entry_processing.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Acknowledgments sent to donor accounts"},{"planet":"campaigns","desc":"Campaign-specific acknowledgment templates"}]}
  ],
  dataFlow: ["Advance fundraising activity into gift entry for a constituent account donor.","Process the gift entry to create or update the Gift Transaction.","Link the transaction to its gift commitment, campaign, and outreach source code.","Allocate the transaction to gift designations and add applicable gift soft credits.","Record payment instrument details, generate acknowledgments, and process any full or partial refund."],
  connections: [{"planet":"gift_commitments","desc":"Transactions fulfill commitments"},{"planet":"gift_entry","desc":"Gift entry creates transactions"},{"planet":"designations","desc":"Transactions linked to designations"},{"planet":"soft_credits","desc":"Transactions have soft credits"},{"planet":"campaigns","desc":"Transactions attributed to campaigns"},{"planet":"constituents","desc":"Donors are constituent accounts"},{"planet":"fundraising","desc":"Pipeline leads to transactions"}]
},

gift_entry: {
  packages: ["nonprofitcloud"],
  name: "Gift Entry & Processing",
  icon: "\u{1F4DD}",
  color: "#d946ef",
  description: "Gift Entry & Processing provides Nonprofit Cloud interfaces and batch workflows for recording, validating, importing, and processing donations. The Gift Entry Window captures a complete gift, while the configurable Gift Entry Grid supports a single gift or batches of up to 200 rows; Gift Batches add shared defaults, dry runs, error correction, and coordinated processing, and CSV Data Management supports large-volume imports. During entry, users select or create donors, create or match gift commitments, and apply designations, campaigns, and outreach source codes, with Agentforce providing AI assistance alongside gift data entry. Processing creates gift transactions and related gift transaction designation and gift soft credit records.",
  components: [
    {id:"gift-entry-window",name:"Gift Entry Window",icon:"\u{1F5BC}",desc:"The Gift Entry Window is the standard guided interface for creating a complete gift entry in Nonprofit Cloud. It supports standalone gifts, gifts added to a batch, new recurring gift commitments, and payments matched to existing commitments. Users can capture donor, payment, campaign, outreach source code, designation, soft credit, and mapped custom-field information in one interface. Standalone entries are processed when saved, while entries associated with a gift batch are processed through the batch workflow.",tags:["GiftEntry"],docs:["The Gift Entry Window can create a standalone gift, create a gift commitment with its first gift transaction, or add an entry to an unprocessed gift batch. The gift can include multiple designations and soft credits. Users select either Individual or Organizational/Household as the gift type and then select or add the corresponding donor. Individual gifts use person accounts, while Organizational/Household gifts use business accounts.","Users record the gift received date, GiftAmount, PaymentMethod, and any applicable outreach source code. Selecting an outreach source code automatically populates the associated campaign. For a gift that fulfills an existing commitment, the Matching Gift Commitments table shows active commitments with unpaid transactions inside the window defined by Installment Extension Day Count. Users can instead select New Recurring Gift and enter the effective dates, transaction period, interval, and transaction day for a new commitment.","Designation Information can contain up to 50 designations for the resulting gift transaction, and Soft Credit Information identifies people, businesses, or household members who receive soft credit. Custom fields mapped in Gift Entry settings appear in the Additional Fields section; that section is hidden when no custom fields are mapped. When entering a batch, users can select Set As Default to reuse the entered values for the next gift entry. Saving an entry that isn't part of a gift batch processes it immediately."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_gift_entry_processing.htm&type=5&language=en_US",connections:[{"planet":"gift_transactions","desc":"Gift entry creates gift transaction records"},{"planet":"gift_commitments","desc":"Gift entry can create new commitments"},{"planet":"designations","desc":"Designations applied during entry"}]},
    {id:"gift-entry-grid",name:"Gift Entry Grid",icon:"\u{1F4CA}",desc:"The Gift Entry Grid provides a configurable tabular interface for rapid gift entry in Nonprofit Cloud. It supports a single gift or multiple gift rows for a batch, with up to 200 rows and their related records in the grid. Templates control the displayed columns, field behavior, windows, and optional postprocessing for single gifts. Users can capture donors, commitments, campaigns, outreach source codes, designations, soft credits, and mapped custom fields without leaving the grid workflow.",tags:["GiftEntry","GiftEntryGridTemplate"],docs:["The Gift Entry Grid opens from a gift batch, the Gift Entries list, or an Account page. A single entry opens with one row, while a batch can open with the estimated number of empty rows; if no estimate is provided, ten rows appear by default and users can add more. Users key across cells to enter gift information and can add up to 200 rows. Salesforce recommends using the Gift Entry Grid in console view to avoid cache errors.","Each row can select an existing donor, create a donor, or edit donor details. Users can set a recurring gift commitment, match a gift transaction, and enter the outreach source code, campaign, designations, and soft credits. Custom fields mapped to GiftTransaction appear as grid columns, while fields mapped to Account, GiftCommitment, or GiftCommitmentSchedule appear in their related windows. Gift Entry can retrieve up to five distinct gift commitments per donor and up to 10 gift transactions per gift received date.","Gift Entry Grid templates are created by cloning the Salesforce Gift Entry Standard Template or another active template. Administrators can reorder, hide, require, relabel, or resize columns and can base columns on GiftEntry fields or Lightning Web Components. Templates can also open windows from columns, and the default single-gift template can include a postprocessing step that receives the GiftEntry or GiftTransaction record ID. To make a customized template selectable for a gift batch, its API name must be added to the Screen Template Name picklist on GiftBatch.","For a single gift, Process Gift processes the row, while Process & New processes it and opens a new entry. For a batch, Save preserves work, Save & Close returns to the batch, Batch Dry Run tests the entries, and Process Batch processes them. If a row fails during batch processing, its error is written to GiftProcessingResult and the remaining eligible rows continue processing. Users can reopen the grid and correct rows that contain errors."],connections:[{"planet":"gift_transactions","desc":"Grid creates multiple gift transactions"},{"planet":"constituents","desc":"Donors looked up or created during entry"}]},
    {id:"gift-batches",name:"Gift Batches",icon:"\u{1F4E6}",desc:"Gift Batches group multiple GiftEntry records so they can be entered, validated, and processed together in Nonprofit Cloud. Each batch selects a Screen Template Name that defines the Gift Entry Grid fields and their display order. Shared defaults can populate common values in new and empty grid rows, while Batch Dry Run validates the batch without creating records. Processing results are available on the batch and its related entries so users can identify errors, correct entries, and run processing again.",tags:["GiftBatch","GiftEntryGridTemplate"],docs:["Users create a GiftBatch from the Gift Batches page and select a Screen Template Name, either the default or an available customized template. Estimated Gift Count and Estimated Batch Value can be supplied for validation, and Total Gift Value Match enables the value check during processing. After saving the batch, users add GiftEntry records and process the collection together. A batch can also receive imported GiftEntry records through CSV Data Management.","Set Batch Defaults applies common values to new and empty rows in the Gift Entry Grid. Supported defaults include gift received date, amount, payment method, outreach source code, campaign, designations, and soft credits. Read-only fields can't be assigned defaults. Users can save and close the defaults interface or save and continue directly to gift entry.","Batch Dry Run simulates processing, validates current data, and reports issues without committing records or creating related records. Gift entries can't be added or edited while the dry run is in progress, but they can be changed after it finishes. Actual processing creates or updates gift transactions, gift transaction designations, gift soft credits, and accounts for new donors. Users review GiftProcessingStatus and GiftProcessingResult on each entry, while the batch Status and last processed date time indicate the overall processing state."],connections:[{"planet":"gift_transactions","desc":"Batch processing creates transactions in bulk"}]},
    {id:"csv-import",name:"CSV Data Import",icon:"\u{1F4C4}",desc:"CSV Data Import extends Nonprofit Cloud gift batch processing to large volumes of donation data. It uses the CSV Data Management common component to create GiftEntry records from a prepared CSV file. Every imported row is associated with an existing GiftBatch by its Batch ID. After import, users review, validate, correct, and process the entries through the standard gift batch workflow.",tags:["GiftBatch","GiftEntry"],docs:["CSV Data Management reduces manual entry and the risk of errors by importing CSV data into Salesforce objects. For donation imports, users first create a GiftBatch and copy its Batch ID. The source file must satisfy CSV File Readiness requirements and include a Batch ID column. The same GiftBatch ID is placed in every gift-entry row that belongs to the batch.","Users import the prepared file with CSV File Import and then open the associated GiftBatch. The imported entries can be reviewed and tested with Batch Dry Run before actual processing. Processing creates or updates the related fundraising records for each valid GiftEntry, including gift transactions, transaction designations, and soft credits where applicable. Entry-level GiftProcessingStatus and GiftProcessingResult values identify records that require correction."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.csv_file_import.htm&type=5&language=en_US",connections:[{"planet":"gift_transactions","desc":"Imported entries become gift transactions after processing"}]}
  ],
  dataFlow: ["Enter gifts in the Gift Entry Window or Gift Entry Grid, or import donation rows with CSV Data Management, using Agentforce assistance where applicable.","Select an existing donor or create a donor during entry.","Set the gift amount, payment method, campaign, outreach source code, designations, and soft credits.","Create a new gift commitment or match the gift to an eligible existing commitment and transaction.","Apply batch defaults, run Batch Dry Run, and correct errors before processing batched entries.","Process the entries to create gift transactions and their related designation and soft credit records."],
  connections: [{"planet":"gift_transactions","desc":"Gift entry creates transactions"},{"planet":"gift_commitments","desc":"Gift entry creates and matches commitments"},{"planet":"constituents","desc":"Donors entered or matched during gift entry"},{"planet":"designations","desc":"Designations applied during entry"},{"planet":"campaigns","desc":"Campaign and source code set during entry"},{"planet":"agentforce","desc":"AI assists gift data entry"}]
},

designations: {
  packages: ["nonprofitcloud"],
  name: "Gift Designations",
  icon: "\u{1F3F7}",
  color: "#14b8a6",
  description: "Gift Designations control how donation amounts are allocated to specific funds and purposes in Nonprofit Cloud. Default designations on campaigns, opportunities, and gift commitments provide inherited allocations, while transaction designations record how each payment is split. Hierarchical logic selects the applicable defaults during gift entry and assigns any unallocated amount to the organization-wide default. Data Processing Engine rollups summarize designation activity for fundraising analysis and connected impact reporting.",
  components: [
    {id:"gift-designations",name:"Gift Designations",icon:"\u{1F4CB}",desc:"Gift Designations in Nonprofit Cloud represent funds established for specific donor-directed purposes, such as relief or community programs. Organizations create active designations and identify one designation as the organization-wide default for unrestricted gift amounts. Designations can be associated with gift commitments, campaigns, and opportunities so that related gifts are allocated automatically. Existing allocations remain unchanged if the organization-wide default is replaced.",tags:["GiftDesignation"],docs:["Create a gift designation from the Gift Designations area and provide a name that identifies the fund or purpose. Mark the designation active so that it can be allocated when gift entries are processed; new designations are saved as active even when Active isn't selected during creation. Select Default when the designation is intended to receive unrestricted gift amounts. Only one gift designation can be the organization-wide default.","Every gift requires at least one allocated designation. If no other designation is defined, or if defined allocation percentages total less than 100%, Nonprofit Cloud assigns the remaining amount to the organization-wide default. Because processing many records under one designation can cause parent-child data skew, organizations should review record volume and create default designations as necessary. Changing the organization-wide default affects only new allocations and doesn't modify existing gift allocations."],connections:[{"planet":"gift_transactions","desc":"Transactions are allocated to designations"},{"planet":"campaigns","desc":"Campaigns can have default designations"},{"planet":"fundraising","desc":"Opportunities link to designations"}]},
    {id:"transaction-designations",name:"Transaction Designations",icon:"\u{1F517}",desc:"Transaction Designations allocate a gift transaction across one or more donor-selected funds in Nonprofit Cloud. A transaction normally inherits designations through gift entry or from its associated gift commitment, but users can add new allocations or override inherited ones. Each allocation records an amount or percentage for the relationship between the transaction and designation. Any unallocated percentage is assigned automatically to the organization-wide default designation.",tags:["GiftTransactionDesignation"],docs:["Users manage allocations from a gift transaction by opening Manage Gift Transaction Designations and adding or modifying rows. The combined percentages can be equal to or less than 100%, and each transaction can have up to 50 designations. If the allocations total less than 100%, Nonprofit Cloud allocates the remaining gift amount to the organization-wide default designation. To preserve accurate record rollups, users shouldn't change a gift transaction's currency after associating it with a transaction designation.","Gift entry can prepopulate transaction designations according to the applicable inheritance hierarchy, and users can review or update them before saving. For a one-time gift entry, designations come from the campaign when available; otherwise, the organization-wide default is used during processing. For an entry matched to a commitment, Nonprofit Cloud first considers designations on the selected transaction, followed by defaults from the transaction campaign, matching commitment, related opportunity, commitment campaign, and organization-wide default. Overriding the campaign during gift entry causes the gift entry's default designations to be used instead of this hierarchy.","When a gift batch is processed, Nonprofit Cloud creates gift transaction designation records for its gift entries. If a gift is allocated to multiple designations, processing splits the gift and creates multiple records according to the percentages and amounts entered. Gift Transaction Designation amounts and names can also be included in supported acknowledgment documents. This preserves the allocation detail associated with each payment."],connections:[{"planet":"gift_transactions","desc":"Each transaction can have multiple designation allocations"}]},
    {id:"default-designations",name:"Default Designations",icon:"\u{2B50}",desc:"Default Designations define how incoming gifts inherit allocations from fundraising records in Nonprofit Cloud. They can be associated with campaigns, opportunities, and gift commitments, and commitment defaults can be reviewed or changed from the commitment record. Hierarchical logic selects the available source for a gift entry or transaction while permitting a manual override. The organization-wide default fills any allocation that isn't otherwise assigned.",tags:["GiftDefaultDesignation"],docs:["From a gift commitment, users can open Manage Gift Default Designations to review defaults inherited from the associated opportunity or campaign. If neither provides a default, the organization-wide default appears with a 100% allocation. Users can add rows or change allocation ratios, provided the combined percentage is no more than 100%. Administrators can expose the Gift Default Designations related list on Campaign and Opportunity records so their allocations can be managed there.","Hierarchical logic determines the default designations inherited by commitments and the transaction designations inherited by gift transactions. A transaction associated with a commitment inherits that commitment's default designations unless a more applicable source or manual override is used during gift entry. When no defaults exist, the full amount is assigned to the organization-wide default; when defaults total less than 100%, the remaining percentage is assigned there. Commitment changes can also use default designations to attribute a commitment and its transactions across multiple campaigns according to the ratio in which those campaigns influenced the gift amount."],connections:[{"planet":"campaigns","desc":"Campaigns define default designations for sourced gifts"},{"planet":"gift_commitments","desc":"Commitments inherit designations from opportunities and campaigns"},{"planet":"gift_entry","desc":"Gift entry inherits default designations"}]},
    {id:"designation-reporting",name:"Designation Reporting",icon:"\u{1F4CA}",desc:"Designation Reporting surfaces giving metrics for designated funds in the Philanthropy and Partnerships app in Nonprofit Cloud. The Gift Designation Summary appears on the Gift Designation page after the required rollups are configured. Data Processing Engine definitions calculate and refresh designation-related rollups, with nightly recalculation provided by default and customizable scheduling available. Designation allocation data can also feed impact reporting for connected outcomes analysis.",tags:["GiftDesignation"],docs:["The Philanthropy and Partnerships app provides a Gift Designation Summary on each Gift Designation page. If the summary isn't visible, the required rollup setup may not have been completed. The summary presents gift-designation metrics at a glance alongside the app's broader donor and giving metrics. Designation data can also support connected impact reporting that relates funding allocations to outcomes.","To configure fundraising rollups, administrators enable Data Pipelines and clone and activate the supplied GiftDesignation Data Processing Engine template along with the other required fundraising templates. Definitions can be run manually with calendar date inputs, and Salesforce recalculates rollups nightly by default. Administrators can customize the Data Processing Engine schedule or use a schedule-triggered flow with the Manage Fundraising DPE Definitions invocable action to automate updates. Users running or configuring the definitions need access to the objects and fields used by them."],connections:[{"planet":"outcomes","desc":"Designation data supports impact and outcome reporting"}]}
  ],
  dataFlow: ["Create active gift designations and select the organization-wide default.","Assign default designations to campaigns, opportunities, and gift commitments.","Inherit the applicable defaults when commitments and gift entries are created or matched.","Review or override allocations during gift entry and transaction processing.","Create transaction designation records that split each payment by amount and percentage.","Run Data Processing Engine rollups and use designation results in fundraising and impact reporting."],
  connections: [{"planet":"gift_transactions","desc":"Transactions allocated to designations"},{"planet":"gift_commitments","desc":"Commitments inherit designations"},{"planet":"fundraising","desc":"Opportunities link to designations"},{"planet":"campaigns","desc":"Campaigns have default designations"},{"planet":"gift_entry","desc":"Gift entry applies designations"},{"planet":"outcomes","desc":"Designation data feeds impact reporting"},{"planet":"setup","desc":"DPE calculates designation rollups"}]
},

soft_credits: {
  packages: ["nonprofitcloud"],
  name: "Soft Credits",
  icon: "\u{1F31F}",
  color: "#a855f7",
  description: "Soft Credits in Nonprofit Cloud recognize constituents who influenced a gift without making them the primary donor. GiftSoftCredit records associate recipients, roles, and partial amounts with Gift Transactions, while gift default soft credits on Gift Commitments apply attribution across the commitment’s gifts. Constituent relationships inform attribution, and Opportunity contact roles in Fundraising drive soft-credit recognition. Soft-credit data is available for gift entry and processing, donor engagement, segmentation, donor portals, and fundraising rollups.",
  components: [
    {id:"gift-soft-credits",name:"Gift Soft Credits",icon:"\u{2728}",desc:"Gift Soft Credits recognize constituents other than the donor for influencing a gift in Nonprofit Cloud. A soft credit associates a recipient, a partial amount or percentage, and a Role with a Gift Transaction. Gift default soft credits on a Gift Commitment apply to every gift that is part of that commitment. The resulting data supports donor engagement, segmentation, gift processing, donor portals, and fundraising rollups.",tags:["GiftSoftCredit"],docs:["On a Gift Transaction, use Gift Soft Credit to recognize a constituent who helped bring in the donor’s gift. Select the recipient, define the partial percentage or PartialAmount of the transaction, and select the Role of the soft credit recipient. For example, Matched Donor can identify the recipient’s role, and tribute honorees can also be recognized as soft credit recipients. A transaction-level soft credit can be up to 100 percent of the gift.","Gift default soft credits capture influence at the Gift Commitment level. From the Gift Default Soft Credits related list, select the recipient, enter an amount or percentage, and select the Role of the soft credit recipient. The default then applies to all gifts that are part of the selected Gift Commitment. At the commitment level, the soft credit can be greater than 100 percent of the gift.","Soft credits can be entered in the Gift Entry window or Gift Entry Grid along with the gift’s donor, campaign, designations, and other details. The Process Gift Entries flow generates the Gift Transaction, Gift Transaction Designation, and Gift Soft Credit records, and multiple recipients produce multiple Gift Soft Credit records for the transaction. The Soft Credit flow screen component can associate up to 50 soft credit records with a gift entry.","Data Processing Engine calculations include soft-credit metrics in the Donor Giving Summary, including counts, first, last, and highest soft-credit amounts and dates, and combined hard- and soft-credit totals. Household rollups collect soft credits received by household members and remove duplicate soft credits tied to the same Gift Transaction. Donor portals created with Experience Cloud can also show information related to soft credits."],connections:[{"planet":"gift_transactions","desc":"Soft credits are linked to gift transactions"},{"planet":"constituents","desc":"Credits attributed to constituent accounts"},{"planet":"relationships","desc":"Relationships inform soft credit decisions"}]},
    {id:"matching-gift-tracking",name:"Matching Gift Tracking",icon:"\u{1F91D}",desc:"Matching Gift Tracking represents a matching gift from an employer or another organization as a Gift Transaction in Nonprofit Cloud. The matching transaction is linked to the relevant initial donation through the Matching Employer Transaction lookup on the initial Gift Transaction. A Gift Soft Credit with the Matched Donor Role can recognize the constituent associated with the match.",tags:["GiftTransaction"],docs:["Record a matching gift as a Gift Transaction from the organization that provides the match. Matching gifts have no schedule or previous commitment, so opportunities and Gift Commitments aren’t typically necessary. After entering the matching gift, update the Matching Employer Transaction lookup on the Gift Transaction for the initial donation with the newly created matching gift.","Use a Gift Soft Credit to recognize the constituent connected to the matching gift without changing the donor on the matching transaction. Select the recipient, define the partial percentage or PartialAmount, and select Matched Donor as the Role when appropriate. Soft-credit information can be entered during gift entry or added from the related list on the Gift Transaction."],connections:[{"planet":"gift_transactions","desc":"Matching transactions link to original gifts"},{"planet":"constituents","desc":"Matching employers are organization accounts"}]},
    {id:"tribute-gifts",name:"Tribute & Memorial Gifts",icon:"\u{1F339}",desc:"Tribute & Memorial Gifts use Gift Tribute records to capture tribute information associated with a Gift Transaction or Gift Commitment in Nonprofit Cloud. A tribute honoree can also be recognized as a Gift Soft Credit recipient. Tribute details can be included in gift acknowledgments and tax receipt templates.",tags:["GiftSoftCredit"],docs:["Gift Tribute records can be related to a Gift Commitment or Gift Transaction. Supported tribute data for acknowledgment templates includes HonoreeName, NotificationChannel, NotificationContactName, NotificationDate, and NotificationStatus. When appropriate, add the tribute honoree as a Gift Soft Credit recipient on the related Gift Transaction to recognize the honoree.","Gift Entry Grid templates can include a postprocessing step for actions that require the generated Gift Transaction or Gift Entry record ID. The documentation provides creating a Gift Tribute as an example of such a postprocessing step after a single gift is processed. This approach lets an organization capture the tribute after Nonprofit Cloud creates the related Gift Transaction."],connections:[{"planet":"gift_transactions","desc":"Tribute gifts are recorded as transactions with soft credits"},{"planet":"constituents","desc":"Honorees are constituent accounts"}]}
  ],
  dataFlow: ["Use constituent relationships and Opportunity contact roles to identify potential soft-credit recipients.","Enter or process the donation as a Gift Transaction, optionally through a Gift Commitment.","Select each recipient, define the partial amount or percentage, and select the recipient’s Role.","Create GiftSoftCredit records for the Gift Transaction or apply Gift Commitment defaults across its gifts.","Roll up soft-credit data for constituent engagement, segmentation, portals, and fundraising analysis."],
  connections: [{"planet":"gift_transactions","desc":"Soft credits on transactions"},{"planet":"constituents","desc":"Credits attributed to constituents"},{"planet":"relationships","desc":"Relationships inform attribution"},{"planet":"fundraising","desc":"Opportunity contact roles drive soft credits"}]
},

campaigns: {
  packages: ["nonprofitcloud"],
  name: "Campaigns & Outreach",
  icon: "\u{1F4E3}",
  color: "#3b82f6",
  description: "Campaigns & Outreach manages multichannel fundraising efforts in Nonprofit Cloud by connecting campaigns and Outreach Source Codes to gift entry, gift commitments, gift transactions, and Gift Default Designations. Campaign communications can use household, account, contact, and Contact Point Address information, while Action Plans define repeatable tasks for campaign-related fundraising work. Data Processing Engine produces Outreach Summary rollups, and Fundraising Intelligence uses the Mass Market Insights and Fundraising Performance Insights dashboards to analyze campaign performance. Agentforce for Fundraising is documented for donor support, donor engagement notes and tasks, and philanthropic research rather than campaign-performance insights.",
  components: [
    {id:"campaign-management",name:"Campaign Management",icon:"\u{1F4CB}",desc:"Campaign Management organizes multichannel fundraising efforts in Nonprofit Cloud around standard Salesforce campaigns. Campaigns can be associated with gift commitments and gift transactions and can supply Gift Default Designations for related gifts. Campaign communications can use constituent mailing addresses and Contact Point Address records, including primary, seasonal, and undeliverable address information. Action Plans can define repeatable tasks for capital campaigns and other fundraising activities.",tags:["Campaign"],docs:["The Donor Engagement app provides access to campaigns, Outreach Source Codes, gift commitments, and reports for managing mass-market fundraising efforts. Fundraisers who create and manage campaigns require the Marketing User permission. Interest Tags can be assigned to campaigns to provide at-a-glance information about a campaign’s purpose and related interests.","Campaigns participate in gift designation inheritance. Gift commitments can inherit Gift Default Designations from an associated campaign when a higher-priority opportunity designation isn’t available, and gift transactions created during gift entry can inherit designations from the campaign associated with the transaction. If allocations total less than 100%, Nonprofit Cloud allocates the remainder to the org-wide default designation.","Campaign outreach can use account and contact address fields as well as Contact Point Address records. Contact Point Address supports multiple or seasonal addresses and the Is Primary and Is Undeliverable indicators, helping users select current addresses for mailed outreach. Action Plans can also define required tasks for processes such as a capital campaign or other fundraising activities, with templates capturing repeatable work."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_outreach_source_code_campaigns.htm&type=5&language=en_US",connections:[{"planet":"fundraising","desc":"Campaigns source fundraising opportunities"},{"planet":"gift_transactions","desc":"Transactions attributed to campaigns"},{"planet":"gift_commitments","desc":"Commitments linked to campaigns"}]},
    {id:"outreach-source-codes",name:"Outreach Source Codes",icon:"\u{1F4F1}",desc:"Outreach Source Codes identify the outreach methods used within campaigns in Nonprofit Cloud. They distinguish individual appeals by message, channel, audience, and status so fundraisers can compare which approaches lead to donations. Codes can be created individually or in bulk and can be generated automatically from a configured formula. During gift entry, selecting an Outreach Source Code automatically populates its associated campaign.",tags:["OutreachSourceCode"],docs:["A campaign can have multiple Outreach Source Codes for different outreach methods, such as mass mailings, web advertisements, or fundraising events. Users can record audience and message details for each code, including message content and message channel information. Interest Tags can also be assigned to Outreach Source Codes to improve the organization and visibility of audience information.","Admins can turn on Outreach Source Code Generation and configure the Code Formula Structure in Fundraising Settings. The formula can combine reference fields, functions, and operators, and its syntax must be validated before it is saved. Bulk creation lets users create codes for multiple message channels from a campaign page and enter outreach details in a table before generating and saving the codes.","For digital outreach, each Outreach Source Code can have one generated URL that uses UTM parameters configured in Fundraising Settings. The parameters identify the source, medium, and campaign that directed a donor or constituent to the target page. Fundraisers generate the URL from the Outreach Source Code record by entering the giving page or other target URL."],connections:[{"planet":"gift_transactions","desc":"Transactions attributed to specific source codes"},{"planet":"gift_entry","desc":"Source codes set during gift entry"}]},
    {id:"campaign-attribution",name:"Campaign Attribution",icon:"\u{1F3AF}",desc:"Campaign Attribution connects fundraising results to the campaigns and Outreach Source Codes that influenced them. Gift commitments can be linked to campaigns, and gift transactions can be attributed to a donor, commitment, and campaign. During gift entry, users can select the Outreach Source Code that solicited a donation, causing the related campaign to populate automatically. Nonprofit Cloud validates that a gift transaction’s selected Outreach Source Code is valid for its campaign.",tags:["Campaign","OutreachSourceCode"],docs:["Users can associate a campaign with a gift commitment when creating the commitment or its schedule. Gift transactions can also be attributed to campaigns, whether they are created through gift entry, generated from a scheduled gift commitment, or entered manually. This attribution connects fundraising records to the outreach effort that sourced the gift.","When a donation is received in response to a solicitation, the fundraiser selects the applicable Outreach Source Code during gift entry or on the gift transaction. Nonprofit Cloud automatically populates the Campaign field from the selected code. A gift transaction validation enforces that the Outreach Source Code is valid for the selected campaign.","Campaign attribution also affects designations. Gift Default Designations can be defined for campaigns and inherited by gift commitments and gift transactions according to the documented Gift Designation Hierarchy. When a recurring gift commitment upgrade is influenced by an additional campaign, Gift Default Designations can attribute the commitment and its transactions to multiple campaigns in proportion to their influence on the gift amount."],connections:[{"planet":"designations","desc":"Campaigns have default designations for sourced gifts"},{"planet":"gift_commitments","desc":"Commitment changes attributed to campaigns"}]},
    {id:"campaign-performance",name:"Campaign Performance",icon:"\u{1F4C8}",desc:"Campaign Performance provides summarized campaign and outreach metrics for evaluating fundraising activity in Nonprofit Cloud. Data Processing Engine generates Outreach Summary rollups that can appear on Campaign and Outreach Source Code pages. Fundraising Intelligence supplies campaign analytics through the Mass Market Insights and Fundraising Performance Insights dashboards. Agentforce for Fundraising supports donor management, donor engagement, and philanthropic research, but the documented campaign-performance insights are provided by Fundraising Intelligence.",tags:["Campaign"],docs:["Outreach Summary data rollups are available on Campaign and Outreach Source Code records after Data Pipelines is enabled and Data Processing Engine is configured. The summaries can display Gift Count, Response Rate, Total Gift Transaction Amount, Donor Count, Onetime Donor Count, Recurring Donor Count, Average Gift Amount, Average Onetime Gift Amount, and Average Recurring Gift Amount. Admins can change the displayed data by editing the Outreach Summary component in Lightning App Builder.","To create fundraising rollups and summaries, admins clone and activate the Outreach Summary Data Processing Engine template. Definitions can be run manually or through a schedule-triggered flow using the Manage Fundraising DPE Definitions invocable action. Campaign and Outreach Source Code summaries update when their components receive data from related records.","Fundraising Intelligence provides Tableau Next dashboards integrated with Data 360 for fundraising analysis. The Mass Market Insights dashboard on the Donor Engagement app home page analyzes campaign performance by campaign and over time, including revenue, donors, return on investment, average gift amount, and cost-to-revenue ratio. The Fundraising Performance Insights dashboard compares campaign revenue, donor counts, and return on investment and identifies leading and trailing campaigns."],connections:[{"planet":"fundraising","desc":"Campaign data feeds fundraising strategy analytics"}]}
  ],
  dataFlow: ["Create campaigns and assign their Gift Default Designations and related Action Plans.","Prepare campaign audiences and use household, account, contact, and Contact Point Address information for outreach.","Create Outreach Source Codes for each message, channel, and audience used by the campaign.","Apply the appropriate Outreach Source Code during gift entry to populate the campaign and attribute gift commitments and gift transactions.","Run Data Processing Engine definitions to update Campaign and Outreach Source Code summary metrics.","Review campaign performance in the Fundraising Intelligence Mass Market Insights and Fundraising Performance Insights dashboards."],
  connections: [{"planet":"fundraising","desc":"Campaigns source fundraising"},{"planet":"gift_transactions","desc":"Transactions attributed to campaigns"},{"planet":"gift_commitments","desc":"Commitments linked to campaigns"},{"planet":"gift_entry","desc":"Source codes applied during entry"},{"planet":"designations","desc":"Campaigns have default designations"},{"planet":"households","desc":"Campaign mailings use household addressing"},{"planet":"contact_points","desc":"Outreach uses contact information"},{"planet":"action_plans","desc":"Campaigns trigger action plans"},{"planet":"agentforce","desc":"AI provides campaign insights"},{"planet":"setup","desc":"DPE aggregates campaign metrics"}]
},

programs: {
  packages: ["nonprofitcloud"],
  name: "Program Management",
  icon: "\u{1F4DA}",
  color: "#22c55e",
  description: "Program Management in Nonprofit Cloud tracks mission-driven programs, constituent participants, enrollments, cohorts, benefits, schedules, sessions, goals, and benefit delivery. Programs can serve case participants, receive grant funding, use volunteer support, and apply Action Plans to repeatable program work. Programs and benefits can be linked to Outcome Management, while Einstein Program and Benefits Summary drafts stakeholder updates and the Participant Management Agent helps staff record benefits, create tasks, and update participant goals. Administrators enable and configure Program Management and its settings through Nonprofit Cloud Setup.",
  components: [
    {id:"program-records",name:"Programs",icon:"\u{1F3EB}",desc:"Programs are the central records for organizing mission-driven services in Nonprofit Cloud. A program captures identifying information, a summary, status, and start and end dates, and serves as the context for benefits, enrollments, cohorts, schedules, and delivery records. Program staff can use standard Salesforce features such as Path to guide program processes and Einstein Program and Benefits Summary to draft progress updates for stakeholders.",tags:["Program"],docs:["Program Management provides the data model and tools for tracking programs, benefits, and benefit disbursements. Organizations can use it for services such as food distribution, youth development, employment readiness, environmental work, and community support. A Program record identifies the initiative and records its summary, status, and operating dates.","Participants can be added to a program and organized into Program Cohorts. Cohorts are useful when a program runs multiple times or serves distinct groups, and they support reporting on how benefits are distributed across those groups. Program records can also support case participants and connect to benefits and goals used in care plans.","Administrators can enable Path for Program records to guide users through a business process and highlight important fields. To draft stakeholder updates, administrators can add the Einstein Summary component to a program page and select the Summarize Program and Benefits prompt template. Einstein Program and Benefits Summary uses Program and Benefit data from Salesforce, and populated source fields produce more complete outputs."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.prog_case_mgmt_prog_mgmt.htm&type=5&language=en_US",connections:[{"planet":"outcomes","desc":"Programs are measured by outcomes"},{"planet":"case_management","desc":"Programs serve case participants"},{"planet":"grantmaking","desc":"Grants fund programs"}]},
    {id:"benefits",name:"Benefits & Services",icon:"\u{1F381}",desc:"Benefits & Services define the goods, services, classes, workshops, coaching, or other assistance delivered through programs in Nonprofit Cloud. Each Benefit can be associated with a Program, Benefit Type, and Unit of Measure and can be marked active. Benefit Schedules and Benefit Sessions organize recurring delivery, while Benefit Assignments connect enrollees to the benefits they are entitled to receive.",tags:["Benefit","BenefitType","UnitOfMeasure"],docs:["A Benefit represents an offering delivered through a program. Benefit Types categorize offerings, such as Distribution, Coaching, or Hands-On Training, and can distinguish goods from services. Units of measure identify how delivery is quantified, such as Kits or Hours.","Program staff create Benefit Schedules according to the recurring pattern for an offering. The schedule establishes session timing and benefit quantity, and Nonprofit Cloud creates Benefit Sessions for scheduled delivery. Benefit sessions can be displayed in Salesforce Calendar to help staff plan work and avoid scheduling conflicts.","When staff add participants to a benefit schedule, Nonprofit Cloud creates Benefit Assignments, Benefit Schedule Assignments, and Benefit Disbursements for those participants. The resulting disbursement reflects the quantity from the associated schedule, and the participant is initially enrolled for the benefit. Service providers and volunteers can also work with assigned benefits, sessions, attendance, and disbursements through a configured Experience Cloud site."],connections:[{"planet":"outcomes","desc":"Benefit delivery drives outcome measurement"}]},
    {id:"enrollment",name:"Program Enrollment",icon:"\u{1F4DD}",desc:"Program Enrollment records a constituent's participation in a program in Nonprofit Cloud. An enrollment associates an Account with a Program and tracks status and participation dates. Enrollments can be grouped into Program Cohorts and represented by Program Cohort Members for delivery and reporting.",tags:["ProgramEnrollment","ProgramCohort","ProgramCohortMember"],docs:["Program staff create enrollments for constituents who apply to or participate in a program. In the school kit distribution example, children already represented by contacts or accounts are enrolled with an Applied status. An active anonymous enrollment can also support disbursements to recipients who aren't individually enrolled.","Program Cohorts organize enrollments into a defined group, such as a geographic area or a particular run of a recurring program. A cohort can have start and end dates and a maximum member count. Program Cohort Member records connect enrollees and enrollments to the cohort and track their enrollment status.","Users can apply Path to Program Enrollment, Program Cohort, and Program Cohort Member records to guide enrollment-related processes. Experience Cloud can provide beneficiaries with a way to view and enroll in programs and benefits and review their assigned enrollments and case information. Cohort and enrollment data can then support reporting on participation and benefit distribution."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_prog_mgmt_enroll_individuals.htm&type=5",connections:[{"planet":"constituents","desc":"Enrollees are constituent accounts"},{"planet":"case_management","desc":"Case referrals lead to program enrollment"}]},
    {id:"benefit-disbursement",name:"Benefit Disbursement",icon:"\u{1F4E4}",desc:"Benefit Disbursement tracks the actual delivery of a benefit to a recipient in Nonprofit Cloud. A disbursement is associated with a Benefit Assignment and records the delivered quantity, completion date, and status. Disbursements can be created from scheduled participation or through ad hoc benefit delivery, and attendance updates can update the corresponding delivery records.",tags:["BenefitDisbursement","BenefitSchedule","BenefitSession","BenefitAssignment"],docs:["Scheduled benefit delivery creates Benefit Disbursements for participants when they are added to a Benefit Schedule. The disbursement reflects the benefit quantity specified by the schedule and is associated with the participant's Benefit Assignment. This structure connects the planned offering, the enrollee's entitlement, and the delivered quantity.","For unscheduled delivery, staff can use New Ad Hoc Benefit Disbursement on a benefit to record recipients as they receive assistance. The school kit distribution example uses Program Enrollment recipients for enrolled children and Anonymous recipients for children who aren't enrolled. Nonprofit Cloud creates the necessary Benefit Assignments and Benefit Disbursements for the benefit participants.","Staff track attendance from the Attendance tab on a Benefit Session and can set participation to Completed, Excused, or Absent. If a participant is excused or absent, staff can set the disbursed quantity to zero because the participant didn't receive the scheduled benefit. Saving attendance changes updates the corresponding disbursements, supporting reporting on attendance and actual delivery."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_prog_mgmt_benefits_tracking.htm&type=5",connections:[{"planet":"constituents","desc":"Disbursements go to participant accounts"},{"planet":"outcomes","desc":"Disbursement data feeds outcome indicators"}]},
    {id:"goal-definitions",name:"Goal Definitions",icon:"\u{1F3C6}",desc:"Goal Definitions provide reusable goals for participant services in Nonprofit Cloud. They can be organized into a hierarchy with parent and child goals and can record a description and status. Goal Definitions can be added to care plan templates, and program staff can use the Participant Management Agent to update participant goals.",tags:["GoalDefinition"],docs:["Organizations can create a hierarchy of Goal Definitions that reflects the milestones participants are expected to reach. In the job readiness example, Hired for Job is a top goal, while communication and technical proficiency improvements are intermediate goals. Parent relationships allow related goals to be organized under broader objectives.","Goal Definitions can be added to a Care Plan Template through the Care Plan Template Goal related list. The template can combine standardized goals with program benefits and then be assigned to participants as a personalized care plan. The Participant Management Agent can help case managers and program staff update goals for participants as part of documentation and record-keeping work."],connections:[{"planet":"outcomes","desc":"Goals connect to outcome definitions and indicators"},{"planet":"case_management","desc":"Care plans reference goal definitions"}]}
  ],
  dataFlow: ["Enable Program Management and configure its settings in Nonprofit Cloud Setup.","Create constituent participants and connect case participants to the programs that serve them.","Define programs supported by grants, volunteers, and repeatable Action Plans.","Enroll participants, organize enrollments into cohorts, and assign benefits.","Schedule benefit sessions, record attendance and disbursements, and update participant goals.","Measure programs with Outcome Management, draft updates with Einstein Program and Benefits Summary, and use the Participant Management Agent for participant record-keeping."],
  connections: [{"planet":"constituents","desc":"Participants are constituents"},{"planet":"outcomes","desc":"Programs measured by outcomes"},{"planet":"case_management","desc":"Programs serve case participants"},{"planet":"grantmaking","desc":"Grants fund programs"},{"planet":"volunteers","desc":"Volunteers support programs"},{"planet":"action_plans","desc":"Action plans automate program steps"},{"planet":"setup","desc":"Program settings in setup"},{"planet":"agentforce","desc":"AI summarizes program benefits"}]
},

case_management: {
  packages: ["nonprofitcloud"],
  name: "Case Management",
  icon: "\u{1F4C2}",
  color: "#0ea5e9",
  description: "Case Management in Nonprofit Cloud equips case managers, social workers, and program staff with tools for participant referral intake, assessments, follow-up, and personalized care plans that can support program enrollment. Interaction Summaries preserve detailed notes, while Einstein Notes Summary summarizes relevant Salesforce data and identifies incomplete actions; Agentforce can separately help case managers record benefits, create tasks, and update participant goals. Outcome Management tracks progress toward outcomes, and action plan templates can standardize repeatable case tasks. Nonprofit Cloud Setup, permission sets, role hierarchy-based sharing, and other security controls help protect sensitive constituent and case information.",
  components: [
    {id:"case-referral-intake",name:"Case Referral Intake",icon:"\u{1F4E5}",desc:"Case Referral Intake in Nonprofit Cloud supports inbound and outbound participant referrals and converts them to cases for assessment and follow-up. Guided flows can streamline intake for staff and program participants. Referral records can track the referral type, referring organization, status, and associated case, and the Referral object supports Path for guided business processes.",tags:["Case","Referral"],docs:["Case Referral Intake provides the intake tools used to process inbound and outbound participant referrals. Staff can convert referrals into cases for assessment and follow-up. Guided flows help standardize the intake process for both team members and program participants.","Admins enable and configure Case Referrals in Nonprofit Cloud Setup with the Case Referral permission set. The Referral object supports Path on Lightning record pages and in the Salesforce mobile app. A configured path can highlight key fields and provide guidance as users advance a referral through its process."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_case_referral_intake.htm&type=5",connections:[{"planet":"constituents","desc":"Referrals involve constituent records"},{"planet":"programs","desc":"Referrals lead to program enrollment"}]},
    {id:"care-plans",name:"Care Plans",icon:"\u{1F4CB}",desc:"Care Plans in Nonprofit Cloud helps staff create, manage, and share personalized plans for program participants. Staff can start with standardized Care Plan Templates and customize each plan for a participant’s needs. Templates can organize relevant benefits and goals, while individual care plans track their status and applicable dates.",tags:["CarePlan","CarePlanTemplate","CarePlanTemplateBenefit","CarePlanTemplateGoal"],docs:["Care Plans provides personalized plans that help individuals overcome challenges and accomplish life goals. A care plan can be associated with a participant and a case, with start and end dates defining its applicable period. Staff can manage and share the plan as the participant works toward its goals.","Care Plan Templates provide a standardized starting point for participant care plans. Care Plan Template Benefit and Care Plan Template Goal records add benefits and goal definitions to a template. In the documented job-readiness example, staff create the Ready for Job Hunting template, add job-readiness benefits and goals, and assign the resulting care plan to program participants.","Admins enable and configure Care Plans in Nonprofit Cloud Setup with the Care Plans Access permission set. The CarePlan object supports Path, which can guide staff through the stages of a care plan and highlight important fields. Care Plan record pages are also candidates for Salesforce Channels when a plan requires complex coordination and collaboration."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.prog_case_mgmt_care_plans.htm&type=5",connections:[{"planet":"programs","desc":"Care plans assign participants to program benefits"},{"planet":"outcomes","desc":"Care plan goals link to outcome measurement"}]},
    {id:"assessments",name:"Assessments & Discovery",icon:"\u{1F50D}",desc:"Assessments & Discovery in Nonprofit Cloud uses Discovery Framework to evaluate program participants during intake and throughout their participation. Staff can design and organize assessments that collect information about participant needs and progress. Assessment tasks can be identified by name and tracked by status.",tags:["AssessmentTask"],docs:["Discovery Framework supports the design and organization of assessments for program participants. Organizations can use these assessments during intake and continue evaluating participants throughout their participation. This provides a structured discovery process within case and program work.","Access to assessment capabilities depends on the appropriate permissions and configuration. The Dynamic Assessment Access permission set provides internal users with access to Dynamic Assessment features and objects. AssessmentTask records provide name and status information for tracking assessment work."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.discovery_framework_prerequisites.htm&language=en_US",connections:[{"planet":"constituents","desc":"Assessments are completed for participant accounts"}]},
    {id:"interaction-summaries",name:"Interaction Summaries",icon:"\u{1F4DD}",desc:"Interaction Summaries in Nonprofit Cloud captures permanent, detailed, and searchable notes from meetings and conversations with participants and other stakeholders. Staff can record meeting notes, next steps, and confidentiality information and find notes from earlier interactions. Einstein Notes Summary uses Salesforce data to summarize notes and identify actions or tasks that were logged but not completed.",tags:["InteractionSummary"],docs:["Interaction Summaries stores detailed notes from conversations with clients, caseworkers, advisors, partners, donors, and other stakeholders. Staff can add next steps, protect note confidentiality, and search for notes from previous interactions. The same feature can document an intake conversation with a program participant or another stakeholder discussion.","Admins enable Interaction Summaries as a Nonprofit Cloud prerequisite. When enabling the feature, Salesforce directs admins to also enable Role Hierarchy–Based Sharing for Interaction Summary, Role Hierarchy–Based Sharing for Interactions, and Enhanced Interaction Note Interface. Users who take detailed notes can be assigned the Interaction Summary permission set.","Einstein Notes Summary helps case managers quickly absorb information about a program participant before the next interaction and identify incomplete actions or tasks recorded in notes. It uses data from the Account, Interaction, and Interaction Summary objects, including MeetingNotes, Name, NextSteps, and Status from Interaction Summary. Admins enable the relevant generative AI settings and add the Einstein Summary component with the Summarize Notes prompt template to an Account record page."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.fsc_enable_config_interaction_summaries.htm&type=5&language=en_US",connections:[{"planet":"constituents","desc":"Interaction notes linked to constituent accounts"},{"planet":"agentforce","desc":"Einstein summarizes interaction notes"}]}
  ],
  dataFlow: ["Configure case features, permissions, sharing, and access controls in Nonprofit Cloud Setup.","Capture inbound or outbound referrals involving constituents and convert appropriate referrals into cases.","Conduct Discovery Framework assessments during intake and throughout participation.","Create participant care plans from templates, standardize repeatable case tasks with action plans, and support program enrollment.","Record Interaction Summaries, generate Einstein Notes Summary results, and use Agentforce to help record benefit delivery and create follow-up tasks.","Measure the benefits delivered through care plans as part of program outcomes in Outcome Management."],
  connections: [{"planet":"constituents","desc":"Cases involve constituents"},{"planet":"programs","desc":"Cases lead to program enrollment"},{"planet":"outcomes","desc":"Case outcomes tracked"},{"planet":"agentforce","desc":"AI summarizes notes"},{"planet":"action_plans","desc":"Action plans automate case steps"},{"planet":"security","desc":"Case data requires access controls"},{"planet":"setup","desc":"Case settings in setup"}]
},

outcomes: {
  packages: ["nonprofitcloud"],
  name: "Outcome Management",
  icon: "\u{1F4C8}",
  color: "#84cc16",
  description: "Outcome Management in Nonprofit Cloud defines an impact strategy or theory of change, collects data, tracks progress, and evaluates program effectiveness. Outcome records describe intended results, Indicator Definition records identify what is measured, and Indicator Result records capture measured values for performance periods. The strategy connects outcomes with programs and supports tracking case outcomes, while collected data can be shared with communities, boards, donors, and other stakeholders. Outcome information also supports grant reporting and donor impact reporting through gift designations.",
  components: [
    {id:"outcome-definitions",name:"Outcome Definitions",icon:"\u{1F3AF}",desc:"Outcome Definitions organizes the Outcome records used to represent intended results in a Nonprofit Cloud impact strategy or theory of change. Outcome records include a Name and Description and can be connected with programs and Indicator Definition records. These connections help organizations evaluate program effectiveness and track case outcomes without introducing a separate Outcome Definition object.",tags:["Outcome"],docs:["Use Outcome records to define the intended results of an organization’s impact strategy or theory of change. Outcome Management supports tracking the programs being run to achieve those intended outcomes and evaluating whether the work is effective. Each Outcome record identifies the result by Name and can provide supporting detail in Description.","Connect Outcome records with programs so that intended results are associated with program delivery. Relate Indicator Definition records to the applicable Outcome to establish how progress is organized for measurement. These relationships also support tracking outcomes associated with case-related work in Nonprofit Cloud."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.outcome_management.htm&type=5",connections:[{"planet":"programs","desc":"Outcomes link to the programs that drive them"},{"planet":"grantmaking","desc":"Outcomes demonstrate impact to grant funders"}]},
    {id:"indicators",name:"Indicators",icon:"\u{1F4CF}",desc:"Indicators organizes the Indicator Definition records used in an outcome strategy. An Indicator Definition identifies a measure by Name and relates it to an Outcome. Indicator Definition records support tracking program performance and determining whether work is achieving intended outcomes.",tags:["IndicatorDefinition"],docs:["Use Indicator Definition records to identify what an organization measures as part of its outcome strategy. Associate each Indicator Definition with an Outcome so that measurement data is interpreted against an intended result. Nonprofit Cloud uses this structure to support program-performance tracking and evaluation.","Indicator Definition works with Indicator Assignment, Indicator Performance Period, and Indicator Result in the Outcome Management data model. These records organize measures, the periods in which performance is evaluated, and the collected results. The documentation does not specify data type, collection frequency, baseline value, or target value fields on IndicatorDefinition."],connections:[{"planet":"programs","desc":"Indicators measure program activities and benefits"}]},
    {id:"indicator-results",name:"Indicator Results",icon:"\u{1F4CA}",desc:"Indicator Results organizes the Indicator Result records that capture collected outcome measurements. Each record can store a ResultValue and MeasurementDate and associate the result with an Indicator Performance Period through IndicatorPerformancePeriodId. These records provide measurement data for tracking progress, evaluating programs, and reporting results.",tags:["IndicatorResult"],docs:["Create Indicator Result records as outcome data is collected for an Indicator Definition. Record the measured value in ResultValue and the applicable date in MeasurementDate. Use IndicatorPerformancePeriodId to associate the measurement with the relevant Indicator Performance Period.","Indicator Result data supports progress evaluation and reporting in Nonprofit Cloud. Einstein Funding Award Summary can use Indicator Performance Period and Indicator Results data to help grantmaking program officers identify whether a grant is meeting milestones and fulfilling requirements. The documented grounding fields for that summary include Indicator Performance Period details and Indicator Results values."],connections:[{"planet":"programs","desc":"Results are collected from program activities"}]},
    {id:"impact-reporting",name:"Impact Reporting",icon:"\u{1F4D1}",desc:"Impact Reporting uses collected Outcome Management data to communicate progress and program effectiveness. Organizations can create outcome reports and share them with communities, boards, donors, and other relevant stakeholders. Outcome data also supports grant reporting and accurate impact reporting to donors through gift designations.",tags:["Outcome","IndicatorDefinition"],docs:["Use the data collected through Outcome Management to create reports on outcomes and program effectiveness. Share those reports with the communities served, the organization’s board, donors, and other relevant stakeholders. Reporting connects the impact strategy with evidence about program delivery and whether intended outcomes are being achieved.","Nonprofit Cloud for Grantmaking works with Outcome Management to measure progress and report results. Indicator Performance Period and Indicator Result data can also contribute to Einstein Funding Award Summary, which helps program officers review whether a grant is meeting milestones and fulfilling requirements. This connection supports grant reporting and funding-award evaluation.","Gift designations allocate donations to specific purposes and synchronize allocation data across fundraising records. Nonprofit Cloud uses this synchronized data to provide accurate impact reporting to donors. This enables impact information to be reported in the context of the designation associated with a gift."],connections:[{"planet":"grantmaking","desc":"Impact reports support grant reporting requirements"},{"planet":"designations","desc":"Designation-level impact reporting for donors"}]}
  ],
  dataFlow: ["Define intended results with Outcome records.","Link Outcomes to programs and case-related work.","Create Indicator Definition records for the Outcomes being measured.","Record measured values and dates in Indicator Result records for applicable performance periods.","Evaluate progress and program effectiveness from the collected data.","Report outcomes to stakeholders, grant participants, and donors by designation."],
  connections: [{"planet":"programs","desc":"Programs measured by outcomes"},{"planet":"case_management","desc":"Case outcomes tracked"},{"planet":"grantmaking","desc":"Outcomes support grant reporting"},{"planet":"designations","desc":"Impact reporting by designation"}]
},

volunteers: {
  packages: ["nonprofitcloud"],
  name: "Volunteer Management",
  icon: "\u{1F9D1}\u{200D}\u{1F91D}\u{200D}\u{1F9D1}",
  color: "#eab308",
  description: "Volunteer Management in Nonprofit Cloud coordinates volunteer work from initiative planning and recruitment through matching, scheduling, hour tracking, and reporting. Volunteers are managed as constituents through Person Accounts, while Volunteer Initiatives, Positions, Job Positions, qualifications, shifts, and assignments organize work that supports programs. Volunteer Management Settings, Action Plans, and Agentforce for Nonprofit Cloud support administration, repeatable onboarding, and assisted matching. Experience Cloud sites provide a portal where volunteers can discover opportunities, sign up, complete tasks, and track their participation.",
  components: [
    {id:"volunteer-initiatives",name:"Volunteer Initiatives",icon:"\u{1F3C1}",desc:"Volunteer Initiatives organize volunteer work that helps Nonprofit Cloud users advance organizational and program goals. An initiative can have start and end dates, staffing and hour requirements, a parent initiative, and a published state for Experience Cloud. Job Positions and Job Position Shifts define the work and staffing schedule that serve each initiative. Stage Management and an approval process can support internal progress tracking and review.",tags:["VolunteerInitiative"],docs:["Create a Volunteer Initiative to define a coordinated body of volunteer work. Enter its applicable details, relate it to a parent Volunteer Initiative when it is part of a larger effort, and select Published when it is ready to appear on an Experience Cloud site. The initiative becomes the organizing record for the Job Positions and Job Position Shifts that staff the work.","Volunteer Initiatives can use Stage Management to track progress through stages and internal approvals, such as upcoming, in progress, and completed. Administrators can also set up an approval process for Volunteer Initiatives. After the initiative, Job Positions, and shifts are created, volunteer managers can use matching criteria to find qualified volunteers for the work."],connections:[{"planet":"programs","desc":"Volunteer initiatives support program delivery"},{"planet":"action_plans","desc":"Action plans automate initiative setup tasks"}]},
    {id:"positions-job-positions",name:"Positions & Job Positions",icon:"\u{1F464}",desc:"Positions define reusable functional roles with duties, responsibilities, skills, and qualifications, while Job Positions tailor those roles to specific Volunteer Initiatives. A Position can apply across multiple initiatives, and a Job Position can include its own dates, status, manager, location, qualifications, and shifts. Position Qualifications apply across related Job Positions, while Job Position Qualifications are additive and apply only to a specific Job Position. Action Plans and Stage Management can support repeatable work and internal processes for these records.",tags:["Position","JobPosition"],docs:["Create a Position to represent a generic role that can be reused across Volunteer Initiatives. For example, a general Virtual Tutor Position can relate to a more specific Job Position for a subject or time zone. A Position can require internal approval when the corresponding approval process is configured.","Create a Job Position as a specific role that supports a Volunteer Initiative. It can be related to a general Position and can include details such as its title, start and end dates, status, manager, location, and last filled date. From a Job Position record, volunteer managers can create a shift schedule, find volunteers, or assign volunteers.","Use Position Qualifications to define requirements that apply across all Job Positions related to a Position, and use Job Position Qualifications for additional requirements that apply only to one Job Position. A qualification can reference a Competency or Examination, but volunteer matching uses competencies rather than examinations. Qualification Level must be set for qualification-based matching, and matching accepts volunteers whose Qualification Level is equal to or greater than the requirement."],connections:[{"planet":"programs","desc":"Positions align with program service delivery needs"}]},
    {id:"shifts-assignments",name:"Shifts & Assignments",icon:"\u{1F4C5}",desc:"Job Position Shifts define dated and timed work periods for a Job Position, including shift capacity. Job Position Assignments schedule volunteers for a Job Position and can optionally associate them with a specific shift. If no shift is selected, Nonprofit Cloud applies the assignment to the Job Position without creating a specific Job Position Shift. Assignment records support participation status and volunteer-hour tracking.",tags:["JobPositionShift","JobPositionAssignment"],docs:["Create an individual Job Position Shift or use Create a Shift Schedule from a Job Position to create multiple one-time or recurring shifts. Each shift has a start and end date and time, and its maximum number of volunteers limits the number of assignments that count toward capacity. Recurring schedules can be configured with supported recurrence options and an end date or recurrence count.","Use Assign Volunteers to create Job Position Assignments for one or more volunteers. Selecting a shift creates shift-specific assignments, while leaving the shift unselected applies the assignments to the Job Position without creating a specific Job Position Shift. The assignment status can be selected during assignment, and administrators can configure a default Status value in Volunteer Management Settings.","Volunteer managers can add Count Toward Shift Capacity to the Job Position Assignment page layout to control whether an assignment contributes to shift capacity. Assignment records appear on the Job Position Assignments tab after they are created. Volunteer Management uses assignments to schedule coverage, track hours, and align volunteer activities with organizational goals."],connections:[{"planet":"constituents","desc":"Volunteers assigned to shifts are constituent accounts"}]},
    {id:"volunteer-matching",name:"Volunteer Matching",icon:"\u{1F50D}",desc:"Volunteer Matching searches constituent volunteer records for people suited to a Volunteer Initiative's Job Position or Job Position Shift. Matching criteria can include competencies, Qualification Level, date and time, and location availability. Qualification matching is inclusive, so a volunteer whose Qualification Level equals or exceeds the requirement is a match. The Volunteer Management Agent can also identify unfilled shifts and find suitable volunteers.",tags:["PersonCompetency","PersonExamination","PersonLocationAvailability","Competency","Examination"],docs:["Before matching, create volunteers as Person Accounts and record their Person Competencies and Person Location Availabilities. Person Competencies must have a Qualification Level to appear in matching results; matching evaluates Qualification Level rather than Proficiency Level. Position Qualifications and Job Position Qualifications can be selected or excluded from a search, while Examinations aren't used by volunteer matching.","The Search for Volunteers tab supports searches by Volunteer Initiative and Job Position. A manager can match against selected qualifications, a Job Position Shift or date-and-time range, and the Job Position location; date, time, or location matching can also be omitted. Results identify volunteers who already have related Job Position Assignments or Job Position Shifts, and the results can be exported to a CSV file saved to the Job Position record.","Agentforce for Nonprofit Cloud provides the Shift Capacity and Coverage subagent for volunteer managers. Its actions identify unfilled or under-capacity Job Position Shift records and match suitable volunteers to shifts. Volunteer managers can use it to see open roles, identify available people, and find volunteers who best meet the shift criteria."],connections:[{"planet":"constituents","desc":"Matching evaluates volunteer profiles"}]},
    {id:"volunteer-portal",name:"Volunteer Portal",icon:"\u{1F310}",desc:"The Volunteer Portal uses Experience Cloud to publish opportunities and provide volunteer self-service. Volunteers can browse, search, and sign up for opportunities, complete onboarding and training tasks, upload documentation, and track volunteered hours. Published Volunteer Initiatives can be made available through the site. Access is controlled through Volunteer Management permissions for authenticated and guest users.",tags:["VolunteerInitiative"],docs:["Before creating a volunteer portal, enable Digital Experiences and create an Experience Cloud site. A portal can give volunteers a place to register, complete onboarding, attend training or continuing education, view and sign up for volunteer opportunities, upload documentation, and track their volunteered hours. Action Plans can define repeatable onboarding tasks, and Action Plans can be applied to Application Form, Position, and Job Position records.","Assign Manage Volunteer Work in Experience Cloud to authenticated users who use Volunteer Management features in the portal. For guest access, use a customized muting permission set with Volunteer Management in Experience Cloud Guest Access to allow sign-up for volunteer opportunities. Administrators should also review which Nonprofit Cloud objects are available in Experience Cloud and configure the required site license and access."],connections:[{"planet":"constituents","desc":"Portal creates or links to volunteer accounts"},{"planet":"agentforce","desc":"AI agent assists volunteer portal users"}]}
  ],
  dataFlow: ["Enable Volunteer Management in Setup, assign permissions, and configure locations, operating hours, and assignment defaults.","Register volunteers as constituent Person Accounts and record their competencies, examinations, and location availability.","Define Volunteer Initiatives that support programs, then add Positions, Job Positions, qualifications, and Action Plans for onboarding.","Publish eligible initiatives in an Experience Cloud portal so volunteers can browse and sign up for opportunities.","Match volunteers to open work by using qualifications, availability, location, or the Shift Capacity and Coverage subagent.","Create Job Position Shifts and Job Position Assignments, track volunteer hours, and report Volunteer Management metrics."],
  connections: [{"planet":"constituents","desc":"Volunteers are constituents"},{"planet":"programs","desc":"Volunteers support programs"},{"planet":"action_plans","desc":"Action plans automate volunteer onboarding"},{"planet":"agentforce","desc":"AI assists volunteer matching"},{"planet":"setup","desc":"Volunteer settings in setup"}]
},

grantmaking: {
  packages: ["nonprofitcloud"],
  name: "Grantmaking",
  icon: "\u{1F4B5}",
  color: "#f43f5e",
  description: "Grantmaking is an optional Nonprofit Cloud capability for planning, managing, delivering, and measuring outbound grants of currency or goods. It tracks Funding Opportunities, applicant organization accounts, Individual Applications, Application Reviews, budgets, Funding Awards, and grantee collaboration through Experience Cloud. Grants can support programs, and Outcome Management measures progress and reports results. Organization relationships and Action Plans support grant decisions and review work, Einstein Board Version of Grant Application creates a distilled application for board review, and inbound grants received by the organization are managed through Fundraising.",
  components: [
    {id:"funding-opportunities",name:"Funding Opportunities",icon:"\u{1F4E2}",desc:"Funding Opportunities represent outbound grant offerings that funders make available to prospective applicants in Nonprofit Cloud. They capture the opportunity’s purpose, funding amount, application deadline, eligibility criteria, status, and publication state. Published opportunities can be presented through an Experience Cloud portal so grant seekers can learn about available funding. Each opportunity provides the context for related Individual Application and Application Review data.",tags:["FundingOpportunity"],docs:["Nonprofit Cloud for Grantmaking enables funders to create funding opportunities that include application details. A FundingOpportunity record can identify the offering through Name and Description, define its FundingAmount, ApplicationDeadline, and EligibilityCriteria, and track its Status. IsPublished records whether the opportunity is published for applicants.","When Nonprofit Cloud is used with Experience Cloud, grant seekers can learn about funding opportunities and apply for them online. The grantmaking site template helps organizations create a portal for communication and collaboration with grantees. Experience Cloud must be licensed, enabled, and configured, and access to Nonprofit Cloud objects depends on the assigned permissions."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.grmk_grantmaking.htm&type=5",connections:[{"planet":"programs","desc":"Funding opportunities support specific programs"},{"planet":"outcomes","desc":"Grant opportunities specify outcome requirements"}]},
    {id:"grant-applications",name:"Grant Applications",icon:"\u{1F4DD}",desc:"Grant Applications track each applicant organization’s request for a Funding Opportunity as an Individual Application. The application records the requested amount, project narrative, submission date, and current status, while Application Review records capture reviewer evaluations. Nonprofit Cloud supports the review and approval of applications and related budgets, with Action Plans available to organize repeatable review tasks. Einstein Board Version of Grant Application can generate a distilled application version for board review.",tags:["IndividualApplication","ApplicationReview"],docs:["An Individual Application connects a funding request to a Funding Opportunity and an applicant organization account through FundingOpportunityId and AccountId. It records RequestedAmount, ProjectNarrative, Status, and SubmittedDate along with the application Name. Nonprofit Cloud can also track the organizations and people involved in grants, while relationship information can provide context for grant decisions.","Application Review records document evaluations associated with an Individual Application. Review data includes the ReviewerId, Score, Comment, and ApplicationRecommendation, supporting the review and approval process. Action Plans can define repeatable tasks, priorities, assignees, and completion information for business processes such as grant review workflows.","Einstein Board Version of Grant Application generates a distilled version of an Individual Application for board members reviewing it for final approval. The feature uses Individual Application and Application Review data together with Funding Opportunity fields, and it is configured by adding the Einstein Summary component to the individual application page and selecting the Create Board Version Application prompt template. Blank grounding fields can produce incomplete output, so the documented fields should be populated for the best results.","Grantmaking customers that make most grants to organizations can use the Contact + Business Account model. Person Accounts aren’t required for Grantmaking, although they are recommended when an organization also uses other areas of Nonprofit Cloud such as Fundraising or Program Management. This configuration allows applicant organizations to remain represented as business accounts."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_get_started_with_grantmaking.htm&language=en_US",connections:[{"planet":"constituents","desc":"Applicants are organization accounts"},{"planet":"agentforce","desc":"AI generates board-ready summaries of applications"}]},
    {id:"grant-budgets",name:"Grant Budgets & Awards",icon:"\u{1F4B0}",desc:"Grant Budgets & Awards support the approval, delivery, and evaluation stages of outbound grantmaking in Nonprofit Cloud. Budget records distinguish requested and approved amounts by category and preserve the associated justification. Funding Award records identify the approved Individual Application, awardee, amount, award date, and status. Awards can support programs, and Outcome Management can measure progress and report results.",tags:["Budget","FundingAward"],docs:["Nonprofit Cloud supports the review and approval of budgets submitted as part of the grant application process. A Budget record captures Category, RequestedAmount, ApprovedAmount, and Justification so reviewers can compare the requested and approved values. Grant seekers can submit budgets through the Experience Cloud portal when that experience is configured.","A Funding Award represents awarded outbound funding associated with an Individual Application and an awardee. It records Amount, AwardDate, and Status and forms part of the unified view of funding through delivery and evaluation. Approved grants can support nonprofit programs, while Outcome Management connects grantmaking work to progress measurement and results reporting.","Einstein Funding Award Summary helps grantmaking program officers assess the health of a specific grant. It uses Funding Award data together with Funding Award Requirement, Funding Disbursement, Funding Opportunity, Indicator Performance Period, and Indicator Results data to identify whether milestones and requirements are being met. Administrators configure it by adding the Einstein Summary component to the funding award page and selecting the Summarize Funding Award prompt template."],connections:[{"planet":"fundraising","desc":"Inbound grants use the fundraising pipeline"},{"planet":"programs","desc":"Awards fund specific program activities"}]},
    {id:"grantee-portal",name:"Grantee Portal",icon:"\u{1F310}",desc:"The Grantee Portal uses an Experience Cloud site template to provide online communication and collaboration between funders and grantees. Grant seekers can learn about funding opportunities, apply for funding, submit budgets, and upload supporting documents. The portal extends the grantmaking process to external participants while keeping application information in Nonprofit Cloud. Experience Cloud licensing, configuration, and object permissions govern access.",tags:["FundingOpportunity","IndividualApplication"],docs:["Nonprofit Cloud for Grantmaking includes a site template for Experience Cloud that helps funders create an online portal for grantee communication and collaboration. Through this experience, grant seekers can learn about funding opportunities and submit applications. They can also submit budgets and upload supporting documents as part of the grant process.","To establish the portal, an organization must have the necessary Experience Cloud license and enable and configure Experience Cloud in its Salesforce org. Administrators review permission sets to determine which Nonprofit Cloud objects are available to community users. The resulting site gives applicants and grantees an external collaboration channel connected to the grantmaking records managed by internal staff."],connections:[{"planet":"outcomes","desc":"Grantees report outcomes through the portal"}]}
  ],
  dataFlow: ["Create and publish a Funding Opportunity for grant seekers in the Experience Cloud portal.","Capture the applicant organization account, Individual Application, supporting documents, and budget, using organization relationships as decision context.","Evaluate the Individual Application with Application Review records and Action Plan tasks, and generate an Einstein Board Version of Grant Application when needed.","Approve the budget, create the Funding Award, and direct the outbound grant to supported programs.","Collaborate with the grantee through Experience Cloud and monitor award requirements, disbursements, milestones, and status.","Measure grant progress with Outcome Management, and process grants received by the organization through Fundraising."],
  connections: [{"planet":"fundraising","desc":"Inbound grants use the fundraising pipeline"},{"planet":"programs","desc":"Grants fund programs"},{"planet":"outcomes","desc":"Grants measured by outcomes"},{"planet":"constituents","desc":"Applicants are organization accounts"},{"planet":"agentforce","desc":"AI summarizes grant applications"},{"planet":"relationships","desc":"Organization relationships inform grants"},{"planet":"action_plans","desc":"Action plans support grant review workflows"}]
},

agentforce: {
  packages: ["nonprofitcloud"],
  name: "Agentforce & Einstein AI",
  icon: "\u{1F916}",
  color: "#6366f1",
  description: "Agentforce & Einstein AI brings generative and conversational AI capabilities to Nonprofit Cloud across fundraising, program and case management, grantmaking, and volunteer management. Einstein capabilities generate draft gift proposals and summarize programs, interaction notes, funding awards, and grant applications. Agentforce agents support donor research and service, campaign insights, gift entry, participant operations, and volunteer matching through configurable subagents. Administrators enable the required AI settings, configure components or agents, test the experience, and assign access to users.",
  components: [
    {id:"gift-proposals",name:"AI Gift Proposals",icon:"\u{1F4DD}",desc:"AI Gift Proposals brings generative and conversational AI to major-gift fundraising in Nonprofit Cloud. It uses data in the Salesforce org to draft personalized gift proposals that communicate the organization’s mission, tone, and the potential impact of a donor’s contribution. The capability helps major gift officers reduce the time and effort required to prepare proposals for high-net-worth donors.",tags:[],docs:["AI Gift Proposals uses Einstein Copilot and the Copilot Actions: Fundraising Gift Proposals capability to produce draft gift proposals. Major gift officers can ask Einstein Copilot to create a proposal grounded in their organization’s Salesforce data. The generated draft is intended to help officers develop compelling, personalized solicitations.","The capability is available in Lightning Experience with supported Nonprofit Cloud editions and an eligible Einstein add-on. The documented Einstein Copilot capability is a beta service, so use is optional and subject to the applicable Beta Services Terms. Organizations should review generated drafts before using them in donor communications."],connections:[{"planet":"fundraising","desc":"Gift proposals support major gift solicitations"},{"planet":"constituents","desc":"Proposals personalized based on donor data"}]},
    {id:"ai-summaries",name:"Einstein Summaries",icon:"\u{1F4CB}",desc:"Einstein Summaries uses Salesforce data to draft program and benefit summaries, notes summaries, funding award summaries, and streamlined grant applications for board review. These summaries help program managers, case managers, major gift officers, and grantmaking program officers absorb record information and prepare stakeholder updates. The generated content can be copied for use in documents or regenerated to produce another version.",tags:[],docs:["Einstein Program and Benefits Summary drafts updates about a program and its benefits for internal and external stakeholders. Einstein Notes Summary condenses information about constituents, participants, or grantees and can surface actions or tasks recorded in notes that remain incomplete. The grantmaking capabilities summarize funding awards to help officers assess milestones and requirements, and create distilled versions of grant applications for board review.","Administrators first set up the applicable Nonprofit Cloud features and Einstein generative AI, enable Nonprofit Cloud Generative AI Settings and Context Definitions, and then add the Einstein Summary component to Lightning record pages. Each component is configured with the Record Summary prompt template type and the appropriate prompt template. Supported placements include program pages, individual account pages, individual application pages, and funding award pages.","The summaries are grounded in relevant Salesforce records, including programs and benefits, accounts and interaction summaries, grant applications and reviews, and funding awards with related requirements, disbursements, and indicator data. A generation can use up to 100 related records as grounding data. Blank fields aren’t omitted during response generation and can lead to incomplete output, so organizations should populate the relevant source data before generating a summary.","Users open the applicable record and generate the summary from its Einstein Summary pane. They can copy the result into another document or select Generate to receive a different version. The documented summary capabilities are pilot or beta services, consume Einstein Requests, and are subject to the applicable terms."],docUrl:"https://help.salesforce.com/s/articleview?id=ai.generative_ai.htm&type=5",connections:[{"planet":"programs","desc":"AI summarizes program benefits"},{"planet":"case_management","desc":"AI summarizes interaction notes"},{"planet":"grantmaking","desc":"AI creates board-ready grant summaries"}]},
    {id:"volunteer-agent",name:"Volunteer AI Agent",icon:"\u{1F9D1}\u{200D}\u{1F4BB}",desc:"Volunteer AI Agent helps Nonprofit Cloud teams manage volunteer initiatives and shifts with less administrative effort. Its Shift Capacity & Coverage subagent identifies unfilled shifts and finds suitable volunteers to fill them. This assistance supports volunteer matching and can help organizations improve volunteer engagement.",tags:[],docs:["The Volunteer Management Agent supports work involving volunteer shifts and initiatives. In Agent Builder, teams can access the Shift Capacity & Coverage subagent to identify shifts that still need coverage. The subagent then helps find the most suitable volunteers for those shifts.","Before creating the agent, administrators set up Nonprofit Cloud and Einstein generative AI, turn on Agentforce, and enable Agentforce Employee Agents and Einstein Generative AI in Nonprofit Cloud AI Settings. They create the agent from the required template, define its system messages and tone, and add the applicable subagents. The agent must be tested, activated, and assigned to users before it is available to the team."],connections:[{"planet":"volunteers","desc":"AI agent assists volunteer operations"}]},
    {id:"fundraising-agent",name:"Fundraising AI Agent",icon:"\u{1F4B0}",desc:"Fundraising AI Agent applies Agentforce to fundraising initiatives and donor-management workflows in Nonprofit Cloud. Available subagents support philanthropic research and donor requests involving recurring gift commitments. The agent also assists fundraising work involving campaign insights and gift entry, helping teams perform related tasks more efficiently.",tags:[],docs:["Philanthropic Research subagents help fundraising teams optimize donor research and engagement. Teams can use the resulting insights to tailor outreach, develop personalized engagement strategies, and build deeper donor relationships. This research support complements campaign insights used to guide fundraising activity.","The Donor Support Agent uses the Manage Gift Commitments subagent to help donors manage existing gift commitments with recurring schedules through an Experience Cloud site. Supported requests include pausing, resuming, or closing a commitment and updating its amount. Agentforce also assists gift-entry work as part of the connected fundraising workflow.","Administrators create a Nonprofit Cloud agent with the Agentforce Employee Agent template or the template required for the specific agent. They can customize welcome and error messages, set the agent’s tone through language settings, and add the required subagents. After testing the agent for reliable behavior, administrators activate it and assign it to users."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_philanthropic_research_topics_in_agentforce.htm&language=en_US",connections:[{"planet":"campaigns","desc":"AI provides campaign performance insights"},{"planet":"gift_entry","desc":"AI assists with gift data entry"}]}
  ],
  dataFlow: ["Enable Einstein generative AI, Agentforce, and the required Nonprofit Cloud features.","Configure summary components, agent templates, messages, permissions, and subagents.","Ground requests in Salesforce fundraising, program, case, grantmaking, volunteer, campaign, and gift-entry data.","Generate gift proposals, program and note summaries, grant summaries, and board-ready application versions.","Use agents to research donors, surface campaign insights, assist gift entry, and match volunteers to uncovered shifts.","Review generated results, regenerate or copy summaries as needed, and complete the related business workflow."],
  connections: [{"planet":"fundraising","desc":"AI generates gift proposals"},{"planet":"programs","desc":"AI summarizes programs"},{"planet":"case_management","desc":"AI summarizes notes"},{"planet":"grantmaking","desc":"AI summarizes grants"},{"planet":"volunteers","desc":"AI assists volunteer matching"},{"planet":"campaigns","desc":"AI provides campaign insights"},{"planet":"gift_entry","desc":"AI assists gift entry"}]
},

action_plans: {
  packages: ["nonprofitcloud"],
  name: "Action Plans",
  icon: "\u{2705}",
  color: "#fb923c",
  description: "Action Plans in Nonprofit Cloud define and execute the tasks required for repeatable business processes. Templates establish task priorities, assignments, timing, and dependencies, while generated plans track individual work and overall completion against a target record. Action plans drive fundraising cultivation, automate program and case workflows, coordinate volunteer tasks, respond to campaign actions, and support grant review workflows. Stage Management complements action plans by tracking supported records through ordered stages and internal approvals.",
  components: [
    {id:"action-plan-templates",name:"Action Plan Templates",icon:"\u{1F4CB}",desc:"Action Plan Templates capture the repeatable tasks and other items required to complete a business process in Nonprofit Cloud. Templates can support processes such as fundraising activities, program steps, case workflows, volunteer activities, and grant review workflows. Template items define task details such as priority and timing, while the template identifies the type of record to which the resulting plan applies. Active templates provide a consistent foundation for creating action plans.",tags:["ActionPlanTemplate","ActionPlanTemplateItem","ActionPlanTemplateVersion"],docs:["Action plans define the tasks and other items needed to complete a business process. Action Plan Templates capture these repeatable requirements so that staff do not have to define the same process for each record. Nonprofit Cloud documentation identifies capital campaigns, research and development projects, other fundraising activities, and volunteer initiatives as examples of processes that can use action plans.","Each template item describes a task and can specify its priority and timing relative to the start of the plan. Template items can also identify dependencies between tasks through the preceding template item. The template identifies its target object type and must be active when used as the basis for operational plans.","For Volunteer Management, action plans can be applied to Application Form, Position, and Job Position records. The same template-driven approach supports cultivation in fundraising, program steps, case workflows, campaign-triggered processes, and grant review workflows. Administrators should define templates around repeatable organizational processes so that the generated work is consistent."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.fsc_action_plans.htm&type=5&language=en_US",connections:[{"planet":"programs","desc":"Templates automate program enrollment workflows"},{"planet":"volunteers","desc":"Templates automate volunteer onboarding"},{"planet":"fundraising","desc":"Templates drive cultivation step sequences"}]},
    {id:"action-plan-execution",name:"Action Plan Execution",icon:"\u{26A1}",desc:"Action Plan Execution applies a template-defined process to a target record and creates the tasks needed to perform that process. Each task includes a priority, an assignee, and information about when it must be completed. Staff update item statuses as work progresses, while the action plan records overall status and completion percentage. This execution model supports consistent work across fundraising, programs, case management, volunteer management, campaigns, and grantmaking.",tags:["ActionPlan","ActionPlanItem"],docs:["An action plan associates a selected template with a target record and a start date. The template items provide the repeatable task structure for the resulting plan. Each generated action plan item records its assignee, due date, status, and priority.","Users carry out the assigned tasks and update their statuses as the business process advances. The parent action plan tracks its own status and completion percentage, providing a summary of execution across the individual items. Due dates establish when assignees need to complete their work.","Action plans drive fundraising cultivation and can be triggered by campaign actions. They also automate program steps, case workflows, and volunteer tasks, and they support grant review workflows. In Volunteer Management, applicable target records include Application Form, Position, and Job Position."],connections:[{"planet":"case_management","desc":"Action plans automate case management workflows"}]},
    {id:"stage-management",name:"Stage Management",icon:"\u{1F4CA}",desc:"Stage Management tracks the progression of supported Nonprofit Cloud records through defined stages and internal processes. Stage definitions establish an ordered sequence for a particular object type and can associate an Action Plan Template with a stage. In Volunteer Management, stages can represent progress, preparation, fulfillment, review, and approval activities. Stage Management components must be added to the relevant Lightning record pages for users to work with stages.",tags:["StageDefinition"],docs:["Stage Management can track Volunteer Initiative, Job Position Assignment, Job Position Shift, Job Position, Position, and Application Form records. For Volunteer Initiatives, stages can follow progress and internal approvals from upcoming and in progress through completion. For Job Position Shifts, stages can help staff prepare for a shift and track whether it is upcoming or completed.","Stages can support Job Position and Position records as they move from development to fulfillment and through internal review. They can also track Job Position Assignments that require approvals or approval of volunteer hours, and Application Forms that require review and approval. Administrators add Stage Management components to Lightning record pages to expose this tracking to users.","A StageDefinition identifies the applicable object type, the stage's order, and its description. It can also reference an Action Plan Template, connecting a defined stage with a repeatable set of tasks. This structure allows stage tracking and action-plan execution to be configured together where the process requires both."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.stage_management.htm&language=en_US",connections:[{"planet":"volunteers","desc":"Stages track volunteer initiative and assignment progress"},{"planet":"grantmaking","desc":"Stages track application review progress"}]}
  ],
  dataFlow: ["Define an active Action Plan Template for the target business process.","Add ordered template items with task descriptions, priorities, timing offsets, and dependencies.","Apply or trigger the plan for fundraising cultivation, program steps, case workflows, volunteer tasks, campaign actions, or grant review workflows.","Assign generated action plan items to users and calculate their due dates from the plan start date.","Track item statuses, plan status, completion percentage, and applicable record stages.","Complete the assigned tasks and advance the target record through its configured process."],
  connections: [{"planet":"fundraising","desc":"Action plans drive cultivation"},{"planet":"programs","desc":"Action plans automate program steps"},{"planet":"case_management","desc":"Action plans automate case workflows"},{"planet":"volunteers","desc":"Action plans automate volunteer tasks"},{"planet":"campaigns","desc":"Campaign actions trigger plans"},{"planet":"grantmaking","desc":"Action plans support grant review workflows"}]
},

security: {
  packages: ["nonprofitcloud"],
  name: "Security & Access",
  icon: "\u{1F512}",
  color: "#64748b",
  description: "Security & Access manages licenses, permission assignments, and record access for Nonprofit Cloud. Administrators configure managed permission sets and permission set groups in Setup, supplementing them with custom or muting permission sets when organizational requirements differ from the defaults. Sharing settings and channel-specific permissions protect constituent records and control access to case, fundraising, volunteer, and other feature data.",
  components: [
    {id:"permission-set-groups",name:"Permission Set Groups",icon:"\u{1F511}",desc:"Permission set groups consolidate managed Nonprofit Cloud permissions with organization-specific additions or restrictions. Administrators assign the appropriate groups to individual users or multiple users based on the features they need. Combining managed, custom, and muting permission sets in groups preserves access to updated default permissions without requiring administrators to clone managed permission sets.",tags:["PermissionSetGroup"],docs:["Nonprofit Cloud provides managed permission sets for its features, and permission set groups can package the appropriate access for users. For example, users of Fundraising receive the applicable Fundraising permission set groups. Assignments can be made to a single user or multiple users through permission set assignment management.","A permission set group can include the applicable managed permission set together with custom and muting permission sets. This structure lets organizations add org-specific access or remove selected default permissions while continuing to receive updated Nonprofit Cloud permissions. It is the documented alternative to cloning the default permission sets."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.fundraising_editions_and_permissions.htm&language=en_US",connections:[{"planet":"setup","desc":"Permission sets configured in Salesforce setup"}]},
    {id:"permission-set-licenses",name:"Permission Set Licenses",icon:"\u{1F4DC}",desc:"Permission set licenses provide prerequisites for access to certain Salesforce capabilities used with Nonprofit Cloud. Administrators must give users the required licenses before assigning related permissions. For gift acknowledgment document generation, administrators need the DocGen Designer permission set license and the SalesforceCRM Content User license.",tags:["PermissionSetLicense"],docs:["Some Nonprofit Cloud configurations depend on permission set licenses in addition to permission sets or permission set groups. Gift acknowledgment setup requires Salesforce administrators to have the DocGen Designer permission set license and the SalesforceCRM Content User license. All users who generate documents receive the DocGen User permission set.","Required licenses and permissions are assigned according to each user's responsibilities. If the DocGen permission set licenses aren't available in the Salesforce organization, the documentation directs customers to contact their Salesforce account executive. License assignment is therefore a prerequisite that administrators verify during feature setup."],connections:[{"planet":"setup","desc":"Licenses managed in setup"}]},
    {id:"data-security",name:"Data Security & Privacy",icon:"\u{1F6E1}",desc:"Data security and privacy controls determine who can access Nonprofit Cloud records and fields, including constituent and case data. Administrators configure user permissions and organization-wide sharing settings in Setup according to the access required for each feature. Experience Cloud users and guests receive dedicated permissions for supported external access scenarios.",tags:[],docs:["For Fundraising objects, administrators can set organization-wide sharing defaults to Public Read Only or, when broader access is appropriate, Public Read/Write. API integrations that access Fundraising objects use an API Integration user assigned the Fundraising Access permission set. Experience Cloud users can also receive permission sets that provide access to selected Fundraising objects and components.","Access to constituent records and case data is controlled through the permissions configured for the users who work with that information. Volunteer Management distinguishes between internal access, authenticated Experience Cloud access, and guest access by using the Manage Volunteer Data, Manage Volunteer Work in Experience Cloud, and Volunteer Management in Experience Cloud Guest Access permission sets. These assignments let administrators align data access with each user's role and access channel."],connections:[{"planet":"case_management","desc":"Case data requires strict access controls"},{"planet":"constituents","desc":"Donor and participant data is protected"}]},
    {id:"muting-permission-sets",name:"Custom & Muting Permission Sets",icon:"\u{1F507}",desc:"Custom permission sets add access required by organization-specific customizations, such as added fields. Muting permission sets remove selected permissions supplied by a default permission set. Administrators include both types alongside the applicable managed permission set in a permission set group rather than cloning the managed permission set.",tags:["PermissionSetGroup"],docs:["When an organization customizes a Nonprofit Cloud feature, administrators create a custom permission set for the additional permissions. Added fields are one documented reason to create this type of permission set. The custom permission set is then included in a permission set group with the appropriate managed permission set.","To remove permissions supplied by a default permission set, administrators create a muting permission set. They add the muting permission set to the same permission set group as the default and custom permission sets. This design preserves updates to the managed default permissions while allowing the organization to add or remove specific access."],docUrl:"https://help.salesforce.com/s/articleView?id=platform.perm_set_groups_muting.htm&language=en_US",connections:[{"planet":"setup","desc":"Custom permissions configured by admins"}]}
  ],
  dataFlow: ["Identify the Nonprofit Cloud features and data each user needs to access.","Assign any required permission set licenses in Setup.","Combine managed, custom, and muting permission sets in the appropriate permission set groups.","Assign permission sets or permission set groups to individual users or multiple users.","Configure sharing and external-access permissions to protect constituent records and control case data access.","Review assignments when features or organization-specific customizations change."],
  connections: [{"planet":"setup","desc":"Permissions configured in setup"},{"planet":"constituents","desc":"Data security protects constituent records"},{"planet":"case_management","desc":"Case data access controlled"}]
},

setup: {
  packages: ["nonprofitcloud"],
  name: "Setup & Configuration",
  icon: "\u{2699}",
  color: "#78716c",
  description: "Setup & Configuration is the central administration area for enabling and configuring Nonprofit Cloud capabilities, including Fundraising, Program Management, Volunteer Management, Case Management, Outcome Management, and optional Grantmaking. Administrators establish the constituent account model, relationship configuration, permissions, feature-specific settings, fundraising processes, picklists, record types, and sales processes. Data Processing Engine definitions transform organizational data into program and fundraising summaries, including gift designation rollups and campaign or outreach metrics. Scheduled automation keeps calculated results and actionable constituent segments current.",
  components: [
    {id:"feature-enablement",name:"Feature Enablement",icon:"\u{1F504}",desc:"Feature Enablement controls the foundational capabilities used across Nonprofit Cloud. Setup includes selecting an account model, configuring group memberships, assigning permissions, and turning on available features such as Fundraising, Interaction Summaries, Interest Tags, Record Alerts, Timeline, and Actionable Segmentation. Some choices, including enabling Person Accounts and Fundraising, can’t be reversed. Administrators can use Salesforce Go to discover, configure, and monitor available Nonprofit Cloud features and add-on licenses.",tags:[],docs:["Nonprofit Cloud commonly uses Person Accounts to represent individuals, Business Accounts to represent households and other groups, and Group Membership records to connect individuals and organizations. Person Accounts are strongly recommended for organizations using Fundraising or Program Management, but they aren’t required for Grantmaking. Grantmakers that primarily fund organizations and don’t use other Nonprofit Cloud feature areas can instead use the Contact and Business Account model. Because Person Accounts can’t be turned off after activation, administrators must evaluate the account model before enabling them.","Foundational setup includes configuring Data Processing Engine and enabling Actionable Segmentation, which uses summarized constituent data. Administrators can also enable Interaction Summaries, Interest Tags, Record Alerts, and Timeline to support stakeholder history, matching, detailed notes, and proactive follow-up. When Interaction Summaries are enabled, Role Hierarchy–Based Sharing for Interaction Summary and Interactions and the Enhanced Interaction Note Interface must also be enabled. Program, volunteer, case, relationship, and security settings should be configured for the corresponding Nonprofit Cloud workflows and user access.","Fundraising requires the Fundraising_Admin permission set group and must be turned on from Fundraising Settings. Salesforce recommends testing Fundraising in a sandbox because the feature can’t be turned off after activation. Other setup tasks can require feature-specific permission sets, object and field access, page-layout changes, or Flow permissions. Salesforce Go provides a streamlined location for discovering available Nonprofit Cloud features, accessing setup resources, completing configuration, and monitoring usage."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.npc_set_up_nonprofit_cloud.htm&type=5&language=en_US",connections:[{"planet":"programs","desc":"Program Management enabled in setup"},{"planet":"volunteers","desc":"Volunteer Management enabled in setup"},{"planet":"grantmaking","desc":"Grantmaking enabled in setup"}]},
    {id:"fundraising-settings",name:"Fundraising Settings",icon:"\u{1F4B0}",desc:"Fundraising Settings controls gift-processing behavior, donor lookup and matching, gift entry, and selected fundraising capabilities in Nonprofit Cloud. Administrators define the matching window for unpaid installments and the sequential transaction counts that cause commitments to become lapsed or failing. Settings can also automate recurring transaction creation and commitment closure, enable enhanced commitment processing, and configure Gift Entry Grid. Gift validations can be paused temporarily to reduce friction during bulk migrations.",tags:[],docs:["Installment Extension Day Count determines how many days before or after a due date an unpaid gift commitment transaction can match a received gift as an installment. Setting the count to zero creates an exact-date matching window and can incorrectly cause unpaid gifts to become lapsed. Lapsed Unpaid Transaction Count specifies how many sequential unpaid installments change a commitment to Lapsed, while Failing Transaction Count controls when sequential failed installments change it to Failing. A value of zero for either status threshold prevents that status update.","Administrators can select Create Recurring Schedule Transaction to automatically create the next transaction in a recurring schedule; otherwise, it must be created manually. Auto Close Recurring Commitment closes a recurring commitment after its schedule has ended when it has no ongoing or future schedule and no unpaid transactions. NextGen Commitment Processing enables enhanced concurrent processing for recurring gift commitments and is used with a scheduled flow. Administrators can also choose a custom external ID for donor lookup, use duplicate management rules for Business Process API donor matching, and turn on Gift Entry Grid.","Fundraising Settings can temporarily pause validations on gift transactions, gift commitments, and gift commitment schedules during bulk imports or migrations. These validation pauses should be disabled when migration is complete to preserve data integrity. Fundraising Settings also contains configuration used by RFM Score Calculation and can enable capabilities such as Gift Planning, Gift Agreements, and Philanthropic Research Topics in Agentforce. Outreach URL configuration uses organization-defined UTM parameters to identify the source, medium, and campaign associated with digital engagement."],docUrl:"https://help.salesforce.com/s/articleView?id=sfdo.npc_fr_set_up_configure_fundraising.htm&language=en_US",connections:[{"planet":"gift_commitments","desc":"Processing thresholds affect commitment status"},{"planet":"gift_entry","desc":"Gift entry settings configured here"}]},
    {id:"data-processing-engine",name:"Data Processing Engine",icon:"\u{2699}",desc:"Data Processing Engine transforms data in a Nonprofit Cloud org and writes results that create or update records. Definitions can process data from standard objects, custom objects, and Analytics datasets to produce fundraising and program rollups. Fundraising templates calculate donor, gift designation, outreach, and actionable-list summaries, while a separate definition calculates RFM scores. Definitions can be run manually or invoked on a schedule through Flow.",tags:[],docs:["Data Processing Engine requires Data Pipelines and uses definitions to transform source data into calculated results. Nonprofit Cloud uses it to summarize information about donors, volunteers, fundraising efforts, and programs. These summaries support rollup fields and Actionable Segmentation. Users running definitions must have access to every object and field referenced by the definition.","Fundraising setup provides templates for DonorGiftSummary, GiftDesignation, OutreachSummary, and Fundraising Account Actionable List processing. Administrators clone each required template, save it under a new name, activate it, and run the definition with the required calendar date inputs. DonorGiftSummary supports donor and household giving rollups, GiftDesignation produces designation summaries, and OutreachSummary supplies campaign and outreach metrics. Definitions can optionally retain output record counts for selected nodes to support troubleshooting.","Administrators can use a schedule-triggered flow and the Manage Fundraising DPE Definitions action to update fundraising rollups automatically. The flow supplies calendar-year inputs, selects the definitions to run, handles returned batch job IDs, and can wait for job-completion events or follow a fault path. Batch Jobs and Monitor Workflow Services provide job progress and status information. RFM Score Calculation can likewise run manually or through a scheduled flow, with donor scores updated after each completed job."],docUrl:"https://help.salesforce.com/s/articleview?id=ind.dpe_intro.htm&type=5",connections:[{"planet":"designations","desc":"DPE calculates designation rollup totals"},{"planet":"campaigns","desc":"DPE aggregates campaign performance metrics"}]},
    {id:"picklists-record-types",name:"Picklists & Record Types",icon:"\u{1F3F7}",desc:"Picklists & Record Types adapts Nonprofit Cloud records to an organization’s fundraising processes. Administrators can define values such as payment methods, review Gift Vehicle values, and add record types such as Pledge where appropriate. Opportunity record types, stage values, and sales processes can be configured for grant solicitation workflows. Related page layouts and permissions determine how users access the configured process.",tags:[],docs:["Fundraising administrators can create Payment Method picklist values to reflect the methods accepted by the organization. For in-kind gifts, they can review and modify Gift Vehicle picklist values on the Gift Commitment object. Gift entry custom-field mapping supports single-select picklist fields when the source and destination fields have compatible data types. Each mapping must use a unique source field and destination field.","Organizations that manage inbound grant solicitations can configure an Opportunity record type, stage values, and a corresponding Sales Process. Administrators can also create grant-specific Opportunity fields and assign a grant-specific page layout. For other gift workflows, an optional Pledge record type can be added to Gift Commitment. Users who need the resulting functionality must receive the required permissions and page-layout access."],connections:[{"planet":"fundraising","desc":"Opportunity record types define fundraising processes"},{"planet":"relationships","desc":"Relationship role picklists configured here"}]}
  ],
  dataFlow: ["Select the Person Account or Contact and Business Account model, then configure group memberships and relationship types.","Assign setup, feature, object, field, and flow permissions through the applicable permission sets and security configuration.","Enable the required Nonprofit Cloud features and configure program, volunteer, case, and stakeholder settings.","Configure Fundraising thresholds, recurring processing, donor matching, picklists, record types, and sales processes.","Enable Data Pipelines, then clone, activate, and run the required Data Processing Engine definitions.","Schedule Data Processing Engine jobs to refresh designation rollups, campaign metrics, donor scores, program summaries, and segmentation data."],
  connections: [{"planet":"fundraising","desc":"Fundraising settings"},{"planet":"programs","desc":"Program settings"},{"planet":"volunteers","desc":"Volunteer settings"},{"planet":"case_management","desc":"Case settings"},{"planet":"security","desc":"Permissions configured in setup"},{"planet":"constituents","desc":"Account model configured"},{"planet":"relationships","desc":"Relationship types configured"},{"planet":"designations","desc":"DPE calculates rollups"},{"planet":"campaigns","desc":"DPE aggregates metrics"}]
}

};
